// All tunable numbers live here (architecture v2, §9). Phase 2 edition.
import type { CableType, DeviceKind } from './state/types';

// ─── Grid ───────────────────────────────────────────────────────────────────
export const CELL = 48;          // world px per grid cell at scale 1
export const BODY = 40;          // device card size in world px
export const PORT_STUB = 12;     // cable leaves a port straight for this many px
export const ZOOM_MIN = 0.1;
export const ZOOM_MAX = 8;

// ─── Economy ────────────────────────────────────────────────────────────────
export const START_BALANCE = 500;

export const DEVICE_PRICE: Record<DeviceKind, number> = {
  uplink: 0,
  server: 250,
  router: 150,
  switch: 100,
  firewall: 400,
  ddos_scrubber: 600,
};

/** Per-second upkeep cost while the device exists. */
export const DEVICE_UPKEEP: Record<DeviceKind, number> = {
  uplink: 0,
  server: 0.03,
  router: 0.01,
  switch: 0.01,
  firewall: 0.02,
  ddos_scrubber: 0.04,
};

export const CABLE_PRICE: Record<CableType, number> = { ethernet: 5, fibre: 40, crossover: 5 };
export const CABLE_BANDWIDTH: Record<CableType, number> = { ethernet: 1000, fibre: 10000, crossover: 1000 };

// ─── Server tiers ───────────────────────────────────────────────────────────
export const SERVER_SPECS = {
  S: { cpuCores: 2, ramGB: 4, storageGB: 250, nicMbps: 1000 },
  M: { cpuCores: 8, ramGB: 32, storageGB: 1000, nicMbps: 1000 },
  L: { cpuCores: 32, ramGB: 128, storageGB: 4000, nicMbps: 10000 },
} as const;

export const SERVER_PRICE: Record<'S' | 'M' | 'L', number> = { S: 250, M: 600, L: 1500 };

// ─── Uplink ─────────────────────────────────────────────────────────────────
export const UPLINK_START = {
  publicSubnet: '203.0.113.0/28',
  uplinkIp: '203.0.113.1',
  bandwidthMbps: 100,
  uplinkTier: 'basic' as const,
};

export const UPLINK_TIER = {
  basic:    { bandwidthMbps: 100,   costPerSec: 0,    label: 'Basic 100 Mbps' },
  business: { bandwidthMbps: 1000,  costPerSec: 0.05, label: 'Business 1 Gbps' },
  carrier:  { bandwidthMbps: 10000, costPerSec: 0.15, label: 'Carrier 10 Gbps' },
} as const;

// ─── Firewall ───────────────────────────────────────────────────────────────
export const FIREWALL_CAPACITY_MBPS = 1000;
export const DDOS_SCRUBBER_CAPACITY_MBPS = 2000;

// ─── Services ───────────────────────────────────────────────────────────────
/** Revenue per second per unit of demand (demand is 0.7–1.3). */
export const SERVICE_REVENUE: Record<'web_static' | 'web_app', number> = {
  web_static: 0.10,
  web_app: 0.25,
};

/** Per-second reputation recovery rate when a service is up. */
export const REPUTATION_RECOVERY = 0.001;
/** Per-second reputation decay rate when a service is down. */
export const REPUTATION_DECAY = 0.008;

// ─── Simulation timing ─────────────────────────────────────────────────────
/** Ticks per second of real time at speed 1×. */
export const TICKS_PER_SEC = 20;
/** ms per tick at speed 1×. */
export const TICK_MS = 1000 / TICKS_PER_SEC;  // 50ms

/** Carrier packets per flow per second at speed 1×, purely visual. */
export const CARRIER_SPAWN_RATE = 2;
/** Carrier max age in ticks before removal. */
export const CARRIER_MAX_AGE = 100;

// ─── Events ─────────────────────────────────────────────────────────────────
/** Ticks between random hardware failure checks. */
export const FAILURE_CHECK_INTERVAL = 600;  // 30 seconds at 20 tps
/** Base probability of a failure event per check. */
export const FAILURE_BASE_PROB = 0.15;
/** Ticks between DDoS attack attempts. */
export const DDOS_CHECK_INTERVAL = 1200;    // 60 seconds at 20 tps
/** Base probability of a DDoS attack per check. */
export const DDOS_BASE_PROB = 0.10;

// ─── Repairs ────────────────────────────────────────────────────────────────
export const REPAIR_COST_FULL = 100;
export const REPAIR_COST_PREVENTIVE = 40;
/** Ticks to complete a full repair. */
export const REPAIR_DURATION_FULL = 200;      // 10 seconds at 20 tps
/** Ticks to complete a preventive repair. */
export const REPAIR_DURATION_PREVENTIVE = 80; // 4 seconds at 20 tps

// ─── Health thresholds ──────────────────────────────────────────────────────
export const HP_WARNING = 50;
export const HP_CRITICAL = 25;
export const HP_FAILED = 0;

// ─── Stats ──────────────────────────────────────────────────────────────────
/** Number of one-minute buckets for rolling uptime. */
export const UPTIME_BUCKETS = 60;
/** Ticks per bucket (= 1 minute at 20 tps). */
export const TICKS_PER_BUCKET = 1200;
// Port positions, occupancy and L-bend cable routing (architecture v2, §2).
import { BODY, CELL, PORT_STUB } from '../balance';
import type { Cable, Device, DeviceId, Rotation, Side, Vec2, WorldState } from './types';

const SIDES: Side[] = ['N', 'E', 'S', 'W'];
const DIR: Record<Side, Vec2> = { N: { x: 0, y: -1 }, E: { x: 1, y: 0 }, S: { x: 0, y: 1 }, W: { x: -1, y: 0 } };

export const cellKey = (gx: number, gy: number) => `${gx},${gy}`;

export function rotateSide(s: Side, r: Rotation): Side {
  return SIDES[(SIDES.indexOf(s) + r) % 4]!;
}

export function deviceCenter(d: Device): Vec2 {
  return { x: (d.gridPos.gx + 0.5) * CELL, y: (d.gridPos.gy + 0.5) * CELL };
}

export function portSide(d: Device, portIndex: number): Side {
  return rotateSide(d.ports[portIndex]!.side, d.rotation);
}

export function portDir(d: Device, portIndex: number): Vec2 {
  return DIR[portSide(d, portIndex)];
}

export function portPos(d: Device, portIndex: number): Vec2 {
  const p = d.ports[portIndex]!;
  const dir = portDir(d, portIndex);
  const along = { x: -dir.y, y: dir.x };
  const c = deviceCenter(d);
  const t = (p.offset - 0.5) * BODY;
  return { x: c.x + dir.x * (BODY / 2) + along.x * t, y: c.y + dir.y * (BODY / 2) + along.y * t };
}

export function occupancy(state: WorldState): Map<string, DeviceId> {
  const m = new Map<string, DeviceId>();
  for (const d of Object.values(state.devices)) m.set(cellKey(d.gridPos.gx, d.gridPos.gy), d.id);
  return m;
}

/** Map of "deviceId:port" → cableId for every connected port. */
export function portUsage(state: WorldState): Map<string, string> {
  const m = new Map<string, string>();
  for (const c of Object.values(state.cables)) {
    m.set(`${c.a.deviceId}:${c.a.port}`, c.id);
    m.set(`${c.b.deviceId}:${c.b.port}`, c.id);
  }
  return m;
}

export function freePorts(state: WorldState, d: Device, used = portUsage(state)): number[] {
  return d.ports.filter((p) => !used.has(`${d.id}:${p.index}`)).map((p) => p.index);
}

/** Free port of d whose attachment point is nearest to target. */
export function nearestFreePort(state: WorldState, d: Device, target: Vec2): number | null {
  let best: number | null = null;
  let bestDist = Infinity;
  for (const i of freePorts(state, d)) {
    const p = portPos(d, i);
    const dist = Math.hypot(p.x - target.x, p.y - target.y);
    if (dist < bestDist) { bestDist = dist; best = i; }
  }
  return best;
}

/** Port index whose dot is within `radius` world px of point, or null. */
export function portAtPoint(d: Device, pt: Vec2, radius: number): number | null {
  let best: number | null = null;
  let bestDist = radius;
  for (const p of d.ports) {
    const pos = portPos(d, p.index);
    const dist = Math.hypot(pos.x - pt.x, pos.y - pt.y);
    if (dist < bestDist) { bestDist = dist; best = p.index; }
  }
  return best;
}

function cellsOnSegment(a: Vec2, b: Vec2): string[] {
  const len = Math.hypot(b.x - a.x, b.y - a.y);
  const steps = Math.max(1, Math.ceil(len / (CELL / 4)));
  const out: string[] = [];
  for (let i = 0; i <= steps; i++) {
    const x = a.x + ((b.x - a.x) * i) / steps;
    const y = a.y + ((b.y - a.y) * i) / steps;
    out.push(cellKey(Math.floor(x / CELL), Math.floor(y / CELL)));
  }
  return out;
}

function dedupe(points: Vec2[]): Vec2[] {
  const out: Vec2[] = [];
  for (const p of points) {
    const last = out[out.length - 1];
    if (last && Math.abs(last.x - p.x) < 0.01 && Math.abs(last.y - p.y) < 0.01) continue;
    // drop the middle point of three collinear points
    const prev = out[out.length - 2];
    if (prev && last) {
      const collinear = (Math.abs(prev.x - last.x) < 0.01 && Math.abs(last.x - p.x) < 0.01)
        || (Math.abs(prev.y - last.y) < 0.01 && Math.abs(last.y - p.y) < 0.01);
      if (collinear) out.pop();
    }
    out.push(p);
  }
  return out;
}

/**
 * L-bend route: port → short stub → one horizontal + one vertical leg → stub → port.
 * Of the two possible corners, picks the one crossing fewer other devices.
 */
export function routeCable(state: WorldState, cable: Pick<Cable, 'a' | 'b'>, occ = occupancy(state)): Vec2[] {
  const da = state.devices[cable.a.deviceId];
  const db = state.devices[cable.b.deviceId];
  if (!da || !db) return [];
  const a = portPos(da, cable.a.port);
  const b = portPos(db, cable.b.port);
  const dirA = portDir(da, cable.a.port);
  const dirB = portDir(db, cable.b.port);
  const sa = { x: a.x + dirA.x * PORT_STUB, y: a.y + dirA.y * PORT_STUB };
  const sb = { x: b.x + dirB.x * PORT_STUB, y: b.y + dirB.y * PORT_STUB };
  const ends = new Set([cellKey(da.gridPos.gx, da.gridPos.gy), cellKey(db.gridPos.gx, db.gridPos.gy)]);

  const score = (corner: Vec2) => {
    const hit = new Set<string>();
    for (const k of [...cellsOnSegment(sa, corner), ...cellsOnSegment(corner, sb)]) {
      if (occ.has(k) && !ends.has(k)) hit.add(k);
    }
    let s = hit.size * 10;
    // prefer leaving each port in the direction it faces
    const legA = { x: corner.x - sa.x, y: corner.y - sa.y };
    if (legA.x * dirA.x + legA.y * dirA.y < 0) s += 1;
    const legB = { x: corner.x - sb.x, y: corner.y - sb.y };
    if (legB.x * dirB.x + legB.y * dirB.y < 0) s += 1;
    return s;
  };

  const c1 = { x: sb.x, y: sa.y }; // horizontal first
  const c2 = { x: sa.x, y: sb.y }; // vertical first
  const corner = score(c1) <= score(c2) ? c1 : c2;
  return dedupe([a, sa, corner, sb, b]);
}

export function recomputeAllPaths(state: WorldState): void {
  const occ = occupancy(state);
  for (const c of Object.values(state.cables)) c.path = routeCable(state, c, occ);
}

export function distToPolyline(pt: Vec2, path: Vec2[]): number {
  let best = Infinity;
  for (let i = 0; i < path.length - 1; i++) {
    const a = path[i]!;
    const b = path[i + 1]!;
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const len2 = dx * dx + dy * dy;
    const t = len2 === 0 ? 0 : Math.max(0, Math.min(1, ((pt.x - a.x) * dx + (pt.y - a.y) * dy) / len2));
    best = Math.min(best, Math.hypot(pt.x - (a.x + t * dx), pt.y - (a.y + t * dy)));
  }
  return best;
}
// Device registry (architecture v2, §3). Phase 2 edition.
// One entry per kind drives the palette, the factory, port layout and pricing.
// The mapped type makes a missing kind a compile error.
import {
  DDOS_SCRUBBER_CAPACITY_MBPS, DEVICE_PRICE, DEVICE_UPKEEP,
  FIREWALL_CAPACITY_MBPS, SERVER_SPECS, UPLINK_START,
} from '../balance';
import type {
  DeviceId, DeviceKind, DeviceOf, FirewallInterface, GridPos, Health, Port, Side, Usage,
} from './types';

export interface DeviceDef<K extends DeviceKind> {
  kind: K;
  label: string;
  namePrefix: string;
  blurb: string;
  price: number;
  upkeepPerSec: number;
  placeable: boolean; // false = pre-placed only (uplink)
  ports: Omit<Port, 'index' | 'up'>[];
  create(id: DeviceId, name: string, pos: GridPos): DeviceOf<K>;
}

export const freshHealth = (): Health => ({
  hp: 100,
  state: 'ok',
  fault: null,
  faultPort: null,
  degradeRatePerTick: 0,
  repairEndsAt: null,
  repairKind: null,
});

const zeroUsage = (): Usage => ({ cpu: 0, ram: 0, storage: 0, bandwidth: 0 });

function makePorts(spec: Omit<Port, 'index' | 'up'>[]): Port[] {
  return spec.map((p, index) => ({ ...p, index, up: true }));
}

/** Deterministic locally-administered MAC from an id. */
export function macFor(id: string, salt = 0): string {
  let h = 2166136261 ^ salt;
  for (let i = 0; i < id.length; i++) h = Math.imul(h ^ id.charCodeAt(i), 16777619);
  const bytes = [0x02, 0x4e];
  for (let i = 0; i < 4; i++) bytes.push((h >>> (i * 8)) & 255);
  return bytes.map((b) => b.toString(16).padStart(2, '0')).join(':');
}

const side = (s: Side, offset = 0.5, label: string) => ({ side: s, offset, label });

/** Default firewall interfaces for a freshly placed firewall. */
function defaultFwInterfaces(id: DeviceId, ports: Port[]): FirewallInterface[] {
  const defs: { name: string; securityLevel: number }[] = [
    { name: 'outside', securityLevel: 0 },
    { name: 'inside', securityLevel: 100 },
    { name: 'dmz', securityLevel: 50 },
    { name: 'spare', securityLevel: 50 },
  ];
  return ports.map((p, i) => ({
    port: p.index,
    name: defs[i]?.name ?? `if${i}`,
    securityLevel: defs[i]?.securityLevel ?? 50,
    ip: '',
    mask: '255.255.255.0',
    mac: macFor(id, p.index + 100),
  }));
}

export const DEVICE_DEFS: { [K in DeviceKind]: DeviceDef<K> } = {
  uplink: {
    kind: 'uplink',
    label: 'Uplink',
    namePrefix: 'ISP',
    blurb: 'Your connection to the internet',
    price: DEVICE_PRICE.uplink,
    upkeepPerSec: DEVICE_UPKEEP.uplink,
    placeable: false,
    ports: [side('E', 0.5, 'WAN')],
    create(id, name, gridPos) {
      return {
        kind: 'uplink', id, name, gridPos, rotation: 0,
        ports: makePorts(this.ports), health: freshHealth(),
        publicSubnet: UPLINK_START.publicSubnet,
        uplinkIp: UPLINK_START.uplinkIp,
        bandwidthMbps: UPLINK_START.bandwidthMbps,
        uplinkTier: UPLINK_START.uplinkTier,
      };
    },
  },
  server: {
    kind: 'server',
    label: 'Server',
    namePrefix: 'Server',
    blurb: 'Hosts sites and services',
    price: DEVICE_PRICE.server,
    upkeepPerSec: DEVICE_UPKEEP.server,
    placeable: true,
    ports: [side('W', 0.5, 'eth0')],
    create(id, name, gridPos) {
      return {
        kind: 'server', id, name, gridPos, rotation: 0,
        ports: makePorts(this.ports), health: freshHealth(),
        ip: '', mask: '255.255.255.0', gateway: '', mac: macFor(id),
        tier: 'S', specs: { ...SERVER_SPECS.S }, roles: [], usage: zeroUsage(),
      };
    },
  },
  router: {
    kind: 'router',
    label: 'Router',
    namePrefix: 'Router',
    blurb: 'Joins subnets, one IP per port',
    price: DEVICE_PRICE.router,
    upkeepPerSec: DEVICE_UPKEEP.router,
    placeable: true,
    ports: [side('N', 0.5, 'Gi0/0'), side('E', 0.5, 'Gi0/1'), side('S', 0.5, 'Gi0/2'), side('W', 0.5, 'Gi0/3')],
    create(id, name, gridPos) {
      const ports = makePorts(this.ports);
      return {
        kind: 'router', id, name, gridPos, rotation: 0, ports, health: freshHealth(),
        interfaces: ports.map((p) => ({ port: p.index, ip: '', mask: '255.255.255.0', mac: macFor(id, p.index + 1) })),
        routes: [], usage: zeroUsage(),
      };
    },
  },
  switch: {
    kind: 'switch',
    label: 'Switch',
    namePrefix: 'Switch',
    blurb: 'Eight ports on one subnet',
    price: DEVICE_PRICE.switch,
    upkeepPerSec: DEVICE_UPKEEP.switch,
    placeable: true,
    ports: [
      side('N', 0.2, 'p1'), side('N', 0.4, 'p2'), side('N', 0.6, 'p3'), side('N', 0.8, 'p4'),
      side('S', 0.8, 'p5'), side('S', 0.6, 'p6'), side('S', 0.4, 'p7'), side('S', 0.2, 'p8'),
    ],
    create(id, name, gridPos) {
      return { kind: 'switch', id, name, gridPos, rotation: 0, ports: makePorts(this.ports), health: freshHealth(), macTable: {} };
    },
  },
  firewall: {
    kind: 'firewall',
    label: 'Firewall',
    namePrefix: 'Firewall',
    blurb: 'Multi-zone firewall with ACL rules',
    price: DEVICE_PRICE.firewall,
    upkeepPerSec: DEVICE_UPKEEP.firewall,
    placeable: true,
    // 4 ports: outside (W), inside (E), DMZ (S), spare (N)
    ports: [
      side('W', 0.5, 'outside'),
      side('E', 0.5, 'inside'),
      side('S', 0.5, 'dmz'),
      side('N', 0.5, 'spare'),
    ],
    create(id, name, gridPos) {
      const ports = makePorts(this.ports);
      return {
        kind: 'firewall', id, name, gridPos, rotation: 0, ports, health: freshHealth(),
        interfaces: defaultFwInterfaces(id, ports),
        rules: [], defaultPolicy: 'deny', capacityMbps: FIREWALL_CAPACITY_MBPS, usage: zeroUsage(),
      };
    },
  },
  ddos_scrubber: {
    kind: 'ddos_scrubber',
    label: 'DDoS Scrubber',
    namePrefix: 'Scrubber',
    blurb: 'Rate-limits and scrubs attack traffic',
    price: DEVICE_PRICE.ddos_scrubber,
    upkeepPerSec: DEVICE_UPKEEP.ddos_scrubber,
    placeable: true,
    // 2 ports: upstream (W) and downstream (E), inline transparent device
    ports: [side('W', 0.5, 'upstream'), side('E', 0.5, 'downstream')],
    create(id, name, gridPos) {
      return {
        kind: 'ddos_scrubber', id, name, gridPos, rotation: 0,
        ports: makePorts(this.ports), health: freshHealth(),
        rateLimits: [], capacityMbps: DDOS_SCRUBBER_CAPACITY_MBPS,
        synProtection: false, usage: zeroUsage(),
      };
    },
  },
};

export const PLACEABLE_KINDS = (Object.keys(DEVICE_DEFS) as DeviceKind[]).filter((k) => DEVICE_DEFS[k].placeable);

/** Typed lookup that keeps the kind ↔ def correlation. */
export function defOf<K extends DeviceKind>(kind: K): DeviceDef<K> {
  return DEVICE_DEFS[kind] as DeviceDef<K>;
}
// Minimal reactive store (architecture v2, §1). Mutations happen in place inside
// update(); every change carries a reason tag so subscribers can skip work
// they don't care about (e.g. the config panel ignores camera moves).

export type ChangeReason = 'camera' | 'world' | 'ui' | 'load' | 'sim';
export type Listener<T> = (state: T, reason: ChangeReason) => void;

export interface Store<T> {
  get(): T;
  replace(next: T, reason?: ChangeReason): void;
  update(mutate: (draft: T) => void, reason?: ChangeReason): void;
  subscribe(fn: Listener<T>): () => void;
}

export function createStore<T>(initial: T): Store<T> {
  let state = initial;
  const listeners = new Set<Listener<T>>();
  const emit = (reason: ChangeReason) => {
    for (const fn of [...listeners]) fn(state, reason);
  };
  return {
    get: () => state,
    replace(next, reason = 'load') {
      state = next;
      emit(reason);
    },
    update(mutate, reason = 'world') {
      mutate(state);
      emit(reason);
    },
    subscribe(fn) {
      listeners.add(fn);
      return () => listeners.delete(fn);
    },
  };
}
// The two stores (saved world + transient UI) and every world mutation. Phase 2.
import { CABLE_BANDWIDTH, START_BALANCE, UPTIME_BUCKETS } from '../balance';
import { DEVICE_DEFS, defOf } from './devices';
import { cellKey, occupancy, portUsage, recomputeAllPaths, routeCable } from './geometry';
import { createStore } from './store';
import type {
  Cable, CableEnd, CableId, CableType, Device, DeviceId, DeviceKind,
  Economy, GridPos, Rotation, RuntimeCache, Stats, Unlocks, WorldState,
} from './types';

export const SCHEMA_VERSION = 2;

export type Tool =
  | { mode: 'select' }
  | { mode: 'cable' }
  | { mode: 'place'; kind: DeviceKind };

export type Selection = { type: 'device'; id: DeviceId } | { type: 'cable'; id: CableId } | null;

export interface UiState {
  tool: Tool;
  cableType: CableType;
  selection: Selection;
  pendingCable: (CableEnd & { explicit: boolean }) | null;
}

/** High-frequency pointer state, kept apart so panels don't re-render on every mouse move. */
export interface PointerState {
  hoverCell: GridPos | null;
  hoverDevice: DeviceId | null;
  pointerWorld: { x: number; y: number } | null;
  dragGhost: { deviceId: DeviceId; cell: GridPos } | null;
}

function freshEconomy(): Economy {
  return {
    balance: START_BALANCE,
    totalEarned: 0,
    totalSpent: 0,
    revenuePerSec: 0,
    upkeepPerSec: 0,
    repairsCount: 0,
    preventiveRepairs: 0,
  };
}

function freshUnlocks(): Unlocks {
  return {
    macLearning: false,
    connectedRoutes: false,
    serverM: false,
    serverL: false,
    advancedFwRules: false,
    upstreamFiltering: false,
    carrierUplink: false,
    monitoringAgent: false,
  };
}

function freshStats(): Stats {
  return {
    uptimeBuckets: new Array(UPTIME_BUCKETS).fill(1),
    currentBucket: 0,
    bucketTickCount: 0,
    bucketAvailSum: 0,
    ddosBlocked: 0,
    ddosTotal: 0,
    devicesRepaired: 0,
    preventiveRepairs: 0,
    totalDowntimeTicks: 0,
  };
}

export function freshRuntimeCache(): RuntimeCache {
  return {
    paths: {},
    cableLoad: {},
    carriers: [],
    topologyVersion: 0,
    topologyDirty: true,
  };
}

export function newWorld(): WorldState {
  const s: WorldState = {
    meta: { version: SCHEMA_VERSION, seed: (Math.random() * 2 ** 31) | 0, saveTimestamp: 0, playTimeTicks: 0 },
    camera: { x: 0, y: 0, scale: 1 },
    speed: 1,
    economy: freshEconomy(),
    grid: { width: 30, height: 20 },
    devices: {},
    cables: {},
    flows: {},
    services: {},
    events: [],
    activeIncidents: {},
    unlocks: freshUnlocks(),
    stats: freshStats(),
    logs: [],
    time: { tick: 0 },
    nextId: 1,
  };
  const id = nextId(s, 'dev');
  s.devices[id] = DEVICE_DEFS.uplink.create(id, 'ISP Uplink', { gx: 2, gy: 6 });
  return s;
}

export const world = createStore<WorldState>(newWorld());
export const ui = createStore<UiState>({
  tool: { mode: 'select' },
  cableType: 'ethernet',
  selection: null,
  pendingCable: null,
});
export const pointer = createStore<PointerState>({ hoverCell: null, hoverDevice: null, pointerWorld: null, dragGhost: null });

/** Runtime cache lives outside the saved store — rebuilt on load, not serialized. */
export let runtime = freshRuntimeCache();
export function resetRuntime(): void { runtime = freshRuntimeCache(); }

// ---------- toasts ----------
export type ToastKind = 'info' | 'error';
type ToastFn = (msg: string, kind: ToastKind) => void;
const toastListeners = new Set<ToastFn>();
export const onToast = (fn: ToastFn) => { toastListeners.add(fn); return () => toastListeners.delete(fn); };
export const toast = (msg: string, kind: ToastKind = 'info') => toastListeners.forEach((fn) => fn(msg, kind));

// ---------- helpers ----------
function nextId(s: WorldState, prefix: 'dev' | 'cab' | 'rt' | 'fw' | 'flw' | 'svc' | 'inc' | 'rl'): string {
  return `${prefix}_${s.nextId++}`;
}

function nextName(s: WorldState, kind: DeviceKind): string {
  const prefix = DEVICE_DEFS[kind].namePrefix;
  let n = 1;
  const names = new Set(Object.values(s.devices).map((d) => d.name));
  while (names.has(`${prefix}-${n}`)) n++;
  return `${prefix}-${n}`;
}

export function deviceAtCell(s: WorldState, gx: number, gy: number): Device | null {
  const id = occupancy(s).get(cellKey(gx, gy));
  return id ? s.devices[id] ?? null : null;
}

// ---------- mutations ----------
export function placeDevice(kind: DeviceKind, pos: GridPos): DeviceId | null {
  const s = world.get();
  if (!DEVICE_DEFS[kind].placeable) return null;
  if (deviceAtCell(s, pos.gx, pos.gy)) {
    toast('That cell is taken. Pick an empty one.', 'error');
    return null;
  }
  // Economy check
  const price = DEVICE_DEFS[kind].price;
  if (s.economy.balance < price) {
    toast(`Not enough funds ($${s.economy.balance.toFixed(0)} < $${price}).`, 'error');
    return null;
  }
  let created: DeviceId | null = null;
  world.update((w) => {
    const id = nextId(w, 'dev');
    w.devices[id] = defOf(kind).create(id, nextName(w, kind), { ...pos });
    w.economy.balance -= price;
    w.economy.totalSpent += price;
    created = id;
    recomputeAllPaths(w);
    runtime.topologyDirty = true;
  });
  return created;
}

export function deleteDevice(id: DeviceId): void {
  const d = world.get().devices[id];
  if (!d) return;
  if (d.kind === 'uplink') {
    toast('The uplink is your internet connection and cannot be removed.', 'error');
    return;
  }
  world.update((w) => {
    // Remove any services on this device
    for (const [sid, svc] of Object.entries(w.services)) {
      if (svc.serverId === id) {
        // Remove associated flow
        if (svc.flowId && w.flows[svc.flowId]) delete w.flows[svc.flowId];
        delete w.services[sid];
      }
    }
    delete w.devices[id];
    for (const c of Object.values(w.cables)) {
      if (c.a.deviceId === id || c.b.deviceId === id) delete w.cables[c.id];
    }
    recomputeAllPaths(w);
    runtime.topologyDirty = true;
  });
  clearSelectionIf(id);
}

export function moveDevice(id: DeviceId, pos: GridPos): boolean {
  const s = world.get();
  const other = deviceAtCell(s, pos.gx, pos.gy);
  if (other && other.id !== id) {
    toast('That cell is taken.', 'error');
    return false;
  }
  world.update((w) => {
    const d = w.devices[id];
    if (!d) return;
    d.gridPos = { ...pos };
    recomputeAllPaths(w);
  });
  return true;
}

export function rotateDevice(id: DeviceId): void {
  world.update((w) => {
    const d = w.devices[id];
    if (!d) return;
    d.rotation = ((d.rotation + 1) % 4) as Rotation;
    recomputeAllPaths(w);
  });
}

export function connect(a: CableEnd, b: CableEnd, type: CableType): CableId | null {
  const s = world.get();
  if (a.deviceId === b.deviceId) {
    toast('A cable needs two different devices.', 'error');
    return null;
  }
  const used = portUsage(s);
  for (const end of [a, b]) {
    if (used.has(`${end.deviceId}:${end.port}`)) {
      const d = s.devices[end.deviceId];
      toast(`${d?.name ?? 'Device'} ${d?.ports[end.port]?.label ?? ''} already has a cable.`, 'error');
      return null;
    }
  }
  const price = CABLE_BANDWIDTH[type] > 0 ? (
    type === 'fibre' ? 40 : 5
  ) : 5;
  if (s.economy.balance < price) {
    toast(`Not enough funds for cable ($${s.economy.balance.toFixed(0)} < $${price}).`, 'error');
    return null;
  }
  let created: CableId | null = null;
  world.update((w) => {
    const id = nextId(w, 'cab');
    const cable: Cable = { id, a: { ...a }, b: { ...b }, type, bandwidthMbps: CABLE_BANDWIDTH[type], path: [] };
    cable.path = routeCable(w, cable);
    w.cables[id] = cable;
    w.economy.balance -= price;
    w.economy.totalSpent += price;
    created = id;
    runtime.topologyDirty = true;
  });
  return created;
}

export function deleteCable(id: CableId): void {
  world.update((w) => {
    delete w.cables[id];
    runtime.topologyDirty = true;
  });
  clearSelectionIf(id);
}

export function setCableType(id: CableId, type: CableType): void {
  world.update((w) => {
    const c = w.cables[id];
    if (!c) return;
    c.type = type;
    c.bandwidthMbps = CABLE_BANDWIDTH[type];
    runtime.topologyDirty = true;
  });
}

/** Edit a device in place with its narrowed type. */
export function editDevice<K extends DeviceKind>(id: DeviceId, kind: K, fn: (d: Extract<Device, { kind: K }>) => void): void {
  world.update((w) => {
    const d = w.devices[id];
    if (d && d.kind === kind) {
      fn(d as Extract<Device, { kind: K }>);
      runtime.topologyDirty = true;
    }
  });
}

/** Allocate an id for a route, rule, or rate limit. Call inside editDevice(). */
export function genId(prefix: 'rt' | 'fw' | 'rl'): string {
  return nextId(world.get(), prefix);
}

export function resetWorld(): void {
  world.replace(newWorld(), 'load');
  ui.update((u) => { u.selection = null; u.pendingCable = null; }, 'ui');
  resetRuntime();
}

/** Add a log entry (kept to last 100). */
export function addLog(deviceId: string, msg: string, level: 'info' | 'warn' | 'alert' = 'info'): void {
  world.update((w) => {
    w.logs.push({ tick: w.time.tick, deviceId, msg, level });
    if (w.logs.length > 100) w.logs.shift();
  });
}

// ---------- ui helpers ----------
export function setTool(tool: Tool): void {
  ui.update((u) => {
    u.tool = tool;
    u.pendingCable = null;
    if (tool.mode !== 'select') u.selection = null;
  }, 'ui');
}

export function select(sel: Selection): void {
  ui.update((u) => { u.selection = sel; }, 'ui');
}

function clearSelectionIf(id: string): void {
  const sel = ui.get().selection;
  const pend = ui.get().pendingCable;
  if (sel?.id === id || pend?.deviceId === id) {
    ui.update((u) => {
      if (u.selection?.id === id) u.selection = null;
      if (u.pendingCable?.deviceId === id) u.pendingCable = null;
    }, 'ui');
  }
}
// Pointer, touch and keyboard handling. One finger / left mouse: tap acts on
// the current tool, drag pans (or moves the selected device). Two fingers:
// pinch-zoom + pan. Wheel: zoom at cursor. Middle mouse: pan.
import { BODY, CELL, ZOOM_MAX, ZOOM_MIN } from './balance';
import { distToPolyline, nearestFreePort, portAtPoint, portPos, freePorts } from './state/geometry';
import type { Camera, Vec2 } from './state/types';
import {
  connect, deleteCable, deleteDevice, deviceAtCell, moveDevice, placeDevice, pointer, rotateDevice,
  select, setTool, toast, ui, world,
} from './state/world';
import type { Renderer } from './render/renderer';

const TAP_SLOP = 7; // px of movement before a press becomes a drag

type Gesture =
  | { kind: 'none' }
  | { kind: 'press'; x: number; y: number; deviceId: string | null; mouseButton: number }
  | { kind: 'pan'; lastX: number; lastY: number }
  | { kind: 'move'; deviceId: string }
  | { kind: 'pinch'; d0: number; mid0: Vec2; cam0: Camera };

export function setCamera(cam: Camera): void {
  world.update((w) => { w.camera = cam; }, 'camera');
}

export function zoomAt(sx: number, sy: number, factor: number): void {
  const c = world.get().camera;
  const scale = Math.min(ZOOM_MAX, Math.max(ZOOM_MIN, c.scale * factor));
  const wx = (sx - c.x) / c.scale;
  const wy = (sy - c.y) / c.scale;
  setCamera({ scale, x: sx - wx * scale, y: sy - wy * scale });
}

export function fitView(r: Renderer): void {
  const devs = Object.values(world.get().devices);
  const { w, h } = r.screenSize;
  const margin = Math.min(80, Math.max(20, w * 0.06));
  if (devs.length === 0) return;
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const d of devs) {
    minX = Math.min(minX, d.gridPos.gx * CELL);
    minY = Math.min(minY, d.gridPos.gy * CELL);
    maxX = Math.max(maxX, (d.gridPos.gx + 1) * CELL);
    maxY = Math.max(maxY, (d.gridPos.gy + 1) * CELL + 24);
  }
  const bw = Math.max(maxX - minX, CELL * 6);
  const bh = Math.max(maxY - minY, CELL * 4);
  const scale = Math.min(ZOOM_MAX, Math.max(ZOOM_MIN, Math.min((w - margin * 2) / bw, (h - margin * 2) / bh, 1.6)));
  const cx = (minX + maxX) / 2;
  const cy = (minY + maxY) / 2;
  setCamera({ scale, x: w / 2 - cx * scale, y: h / 2 - cy * scale });
}

/** On phones the panel is a bottom sheet; slide the camera so the selected device stays above it. */
export function keepSelectionVisible(r: Renderer): void {
  let last: string | null = null;
  ui.subscribe((u) => {
    const sel = u.selection?.type === 'device' ? u.selection.id : null;
    if (sel === last) return;
    last = sel;
    const { w, h } = r.screenSize;
    if (!sel || w >= 760) return;
    const d = world.get().devices[sel];
    if (!d) return;
    const c = world.get().camera;
    const sy = (d.gridPos.gy + 0.5) * CELL * c.scale + c.y;
    const sheetTop = h * 0.36;
    if (sy > sheetTop - 30) setCamera({ ...c, y: c.y - (sy - h * 0.2) });
  });
}

export function attachInput(r: Renderer, isUiBusy: () => boolean): void {
  const canvas = r.canvas;
  const pointers = new Map<number, Vec2>();
  let gesture: Gesture = { kind: 'none' };

  const local = (e: PointerEvent | WheelEvent): Vec2 => {
    const rect = canvas.getBoundingClientRect();
    return { x: e.clientX - rect.left, y: e.clientY - rect.top };
  };
  const cellOf = (wpt: Vec2) => ({ gx: Math.floor(wpt.x / CELL), gy: Math.floor(wpt.y / CELL) });

  const updateHover = (sp: Vec2 | null) => {
    if (!sp) {
      pointer.update((p) => { p.hoverCell = null; p.hoverDevice = null; p.pointerWorld = null; }, 'ui');
      return;
    }
    const wpt = r.screenToWorld(sp.x, sp.y);
    const cell = cellOf(wpt);
    const dev = deviceAtCell(world.get(), cell.gx, cell.gy);
    pointer.update((p) => {
      p.pointerWorld = wpt;
      p.hoverCell = cell;
      p.hoverDevice = dev?.id ?? null;
    }, 'ui');
  };

  const onTap = (sp: Vec2) => {
    const s = world.get();
    const u = ui.get();
    const wpt = r.screenToWorld(sp.x, sp.y);
    const cell = cellOf(wpt);
    const dev = deviceAtCell(s, cell.gx, cell.gy);
    switch (u.tool.mode) {
      case 'place': {
        placeDevice(u.tool.kind, cell);
        return;
      }
      case 'select': {
        if (dev) return select({ type: 'device', id: dev.id });
        const tol = 8 / s.camera.scale;
        let best: string | null = null;
        let bestD = tol;
        for (const c of Object.values(s.cables)) {
          const d = distToPolyline(wpt, c.path);
          if (d <= bestD) { bestD = d; best = c.id; }
        }
        return select(best ? { type: 'cable', id: best } : null);
      }
      case 'cable': {
        if (!dev) {
          if (u.pendingCable) ui.update((x) => { x.pendingCable = null; }, 'ui');
          return;
        }
        // near a port dot picks that port; the middle of the device leaves the choice to auto-pick
        const radius = Math.min(BODY * 0.35, Math.max(BODY * 0.22, 12 / s.camera.scale));
        const explicit = portAtPoint(dev, wpt, radius);
        if (explicit !== null && freePorts(s, dev).indexOf(explicit) === -1) {
          toast(`${dev.name} ${dev.ports[explicit]!.label} already has a cable.`, 'error');
          return;
        }
        if (!u.pendingCable) {
          if (freePorts(s, dev).length === 0) {
            toast(`${dev.name} has no free ports.`, 'error');
            return;
          }
          ui.update((x) => {
            x.pendingCable = { deviceId: dev.id, port: explicit ?? 0, explicit: explicit !== null };
          }, 'ui');
          return;
        }
        const pend = u.pendingCable;
        const devA = s.devices[pend.deviceId];
        if (!devA) return;
        if (devA.id === dev.id) {
          ui.update((x) => { x.pendingCable = null; }, 'ui');
          return;
        }
        // pick B's port: the one tapped, or the free one nearest A
        const aRef = pend.explicit ? portPos(devA, pend.port) : { x: (devA.gridPos.gx + 0.5) * CELL, y: (devA.gridPos.gy + 0.5) * CELL };
        const portB = explicit ?? nearestFreePort(s, dev, aRef);
        if (portB === null) {
          toast(`${dev.name} has no free ports.`, 'error');
          return;
        }
        const portA = pend.explicit ? pend.port : nearestFreePort(s, devA, portPos(dev, portB));
        if (portA === null) {
          toast(`${devA.name} has no free ports.`, 'error');
          return;
        }
        const id = connect({ deviceId: devA.id, port: portA }, { deviceId: dev.id, port: portB }, u.cableType);
        ui.update((x) => { x.pendingCable = null; }, 'ui');
        if (id) toast(`Connected ${devA.name} ${devA.ports[portA]!.label} → ${dev.name} ${dev.ports[portB]!.label}`);
        return;
      }
    }
  };

  canvas.addEventListener('pointerdown', (e) => {
    canvas.setPointerCapture(e.pointerId);
    const sp = local(e);
    pointers.set(e.pointerId, sp);
    if (pointers.size === 2) {
      const [a, b] = [...pointers.values()] as [Vec2, Vec2];
      pointer.update((p) => { p.dragGhost = null; }, 'ui');
      gesture = {
        kind: 'pinch',
        d0: Math.hypot(a.x - b.x, a.y - b.y) || 1,
        mid0: { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 },
        cam0: { ...world.get().camera },
      };
      return;
    }
    if (pointers.size > 2) return;
    if (e.pointerType === 'mouse' && e.button === 1) {
      e.preventDefault();
      gesture = { kind: 'pan', lastX: sp.x, lastY: sp.y };
      return;
    }
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    const wpt = r.screenToWorld(sp.x, sp.y);
    const cell = cellOf(wpt);
    const dev = deviceAtCell(world.get(), cell.gx, cell.gy);
    gesture = { kind: 'press', x: sp.x, y: sp.y, deviceId: dev?.id ?? null, mouseButton: e.button };
  });

  canvas.addEventListener('pointermove', (e) => {
    const sp = local(e);
    if (pointers.has(e.pointerId)) pointers.set(e.pointerId, sp);

    if (gesture.kind === 'pinch' && pointers.size >= 2) {
      const [a, b] = [...pointers.values()] as [Vec2, Vec2];
      const d = Math.hypot(a.x - b.x, a.y - b.y) || 1;
      const mid = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
      const g = gesture;
      const scale = Math.min(ZOOM_MAX, Math.max(ZOOM_MIN, g.cam0.scale * (d / g.d0)));
      // keep the world point under the starting midpoint under the current midpoint
      const wx = (g.mid0.x - g.cam0.x) / g.cam0.scale;
      const wy = (g.mid0.y - g.cam0.y) / g.cam0.scale;
      setCamera({ scale, x: mid.x - wx * scale, y: mid.y - wy * scale });
      return;
    }

    if (gesture.kind === 'press') {
      if (Math.hypot(sp.x - gesture.x, sp.y - gesture.y) > TAP_SLOP) {
        const u = ui.get();
        const canMove = gesture.deviceId && u.tool.mode === 'select';
        if (canMove) {
          select({ type: 'device', id: gesture.deviceId! });
          gesture = { kind: 'move', deviceId: gesture.deviceId! };
        } else {
          gesture = { kind: 'pan', lastX: gesture.x, lastY: gesture.y };
        }
      }
    }

    if (gesture.kind === 'pan') {
      const c = world.get().camera;
      setCamera({ ...c, x: c.x + (sp.x - gesture.lastX), y: c.y + (sp.y - gesture.lastY) });
      gesture.lastX = sp.x;
      gesture.lastY = sp.y;
    } else if (gesture.kind === 'move') {
      const id = gesture.deviceId;
      const cell = cellOf(r.screenToWorld(sp.x, sp.y));
      pointer.update((p) => { p.dragGhost = { deviceId: id, cell }; }, 'ui');
    }

    // hover (mouse) and rubber-band target (any pointer while a cable is pending)
    if (e.pointerType === 'mouse' || ui.get().pendingCable) updateHover(sp);
  });

  const end = (e: PointerEvent) => {
    const had = pointers.delete(e.pointerId);
    if (!had) return;
    const sp = local(e);
    if (gesture.kind === 'press') {
      onTap(sp);
    } else if (gesture.kind === 'move') {
      const ghost = pointer.get().dragGhost;
      if (ghost) moveDevice(ghost.deviceId, ghost.cell);
      pointer.update((p) => { p.dragGhost = null; }, 'ui');
    }
    if (gesture.kind === 'pinch') {
      // the remaining finger continues as a pan without a jump
      const rest = [...pointers.values()][0];
      gesture = rest ? { kind: 'pan', lastX: rest.x, lastY: rest.y } : { kind: 'none' };
      return;
    }
    if (pointers.size === 0) gesture = { kind: 'none' };
    if (e.pointerType !== 'mouse' && !ui.get().pendingCable) updateHover(null);
  };
  canvas.addEventListener('pointerup', end);
  canvas.addEventListener('pointercancel', (e) => {
    pointers.delete(e.pointerId);
    pointer.update((p) => { p.dragGhost = null; }, 'ui');
    gesture = { kind: 'none' };
  });
  canvas.addEventListener('pointerleave', (e) => {
    if (e.pointerType === 'mouse' && !pointers.size) updateHover(null);
  });

  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    const sp = local(e);
    const delta = e.deltaMode === 1 ? e.deltaY * 16 : e.deltaY;
    zoomAt(sp.x, sp.y, Math.exp(-delta * 0.0015));
  }, { passive: false });

  canvas.addEventListener('contextmenu', (e) => e.preventDefault());

  window.addEventListener('keydown', (e) => {
    if (isUiBusy()) return; // typing in a panel field
    const u = ui.get();
    if (e.key === 'Escape') {
      if (u.pendingCable) ui.update((x) => { x.pendingCable = null; }, 'ui');
      else if (u.tool.mode !== 'select') setTool({ mode: 'select' });
      else select(null);
      return;
    }
    if ((e.key === 'Delete' || e.key === 'Backspace') && u.selection) {
      e.preventDefault();
      if (u.selection.type === 'device') deleteDevice(u.selection.id);
      else deleteCable(u.selection.id);
      return;
    }
    if ((e.key === 'r' || e.key === 'R') && u.selection?.type === 'device') {
      rotateDevice(u.selection.id);
      return;
    }
    if (e.key === 'f' || e.key === 'F') fitView(r);
    // Speed controls: space = toggle pause, 1-3 = speed presets
    if (e.key === ' ') {
      e.preventDefault();
      const spd = world.get().speed;
      world.update((w) => { w.speed = spd === 0 ? 1 : 0; }, 'world');
      return;
    }
    if (e.key === '1') { world.update((w) => { w.speed = 1; }, 'world'); return; }
    if (e.key === '2') { world.update((w) => { w.speed = 2; }, 'world'); return; }
    if (e.key === '3') { world.update((w) => { w.speed = 4; }, 'world'); return; }
  });
}
