// World state schema — Phase 2.
// Adds simulation types (flows, services, economy, events), realistic
// multi-port firewall, DDoS scrubber, uplink IP, and unlock-gated features
// (MAC learning, connected routes).

// ─── Id types ───────────────────────────────────────────────────────────────

export type DeviceId   = string;   // dev_N
export type CableId    = string;   // cab_N
export type FlowId     = string;   // flw_N
export type ServiceId  = string;   // svc_N
export type IncidentId = string;   // inc_N

// ─── Primitives ─────────────────────────────────────────────────────────────

export type Side     = 'N' | 'E' | 'S' | 'W';
export type Rotation = 0 | 1 | 2 | 3;

export interface GridPos { gx: number; gy: number }
export interface Vec2    { x: number; y: number }

// ─── Devices ────────────────────────────────────────────────────────────────

export type DeviceKind =
  | 'uplink'
  | 'server'
  | 'router'
  | 'switch'
  | 'firewall'
  | 'ddos_scrubber';

export interface Port {
  index: number;
  side: Side;       // side before rotation
  offset: number;   // 0..1 position along that side
  label: string;    // eth0, Gi0/1, outside…
  up: boolean;      // false when a NIC fault kills it
}

// ─── Health ─────────────────────────────────────────────────────────────────

export type FaultMode = 'disk' | 'nic' | 'overheat' | 'board';

export interface Health {
  hp: number;                           // 0–100
  state: 'ok' | 'degrading' | 'warning' | 'critical' | 'failed' | 'repairing';
  fault: FaultMode | null;
  faultPort: number | null;             // for nic fault
  degradeRatePerTick: number;           // 0 when healthy
  repairEndsAt: number | null;          // tick
  repairKind: 'preventive' | 'full' | null;
}

// ─── Usage (recomputed each tick) ───────────────────────────────────────────

export interface Usage {
  cpu: number;
  ram: number;
  storage: number;
  bandwidth: number;   // 0–1+, >1 = overloaded
}

// ─── Device base ────────────────────────────────────────────────────────────

interface DeviceBase {
  id: DeviceId;
  name: string;
  gridPos: GridPos;
  rotation: Rotation;
  ports: Port[];
  health: Health;
}

// ─── Uplink ─────────────────────────────────────────────────────────────────
// Pre-placed internet connection. Carries a routable ISP gateway IP so the
// player can type it as next-hop in routers/firewalls.

export interface UplinkDevice extends DeviceBase {
  kind: 'uplink';
  publicSubnet: string;      // e.g. '203.0.113.0/28'
  uplinkIp: string;          // e.g. '203.0.113.1' — ISP gateway, usable as next-hop
  bandwidthMbps: number;     // tier, upgradable
  uplinkTier: 'basic' | 'business' | 'carrier';
}

// ─── Server ─────────────────────────────────────────────────────────────────

export type ServerRole =
  | { role: 'web_static'; serviceId: ServiceId; port: 80 };

export interface ServerDevice extends DeviceBase {
  kind: 'server';
  ip: string;
  mask: string;
  gateway: string;
  mac: string;
  tier: 'S' | 'M' | 'L';
  specs: { cpuCores: number; ramGB: number; storageGB: number; nicMbps: number };
  roles: ServerRole[];
  usage: Usage;
}

// ─── Router ─────────────────────────────────────────────────────────────────

export interface RouterInterface {
  port: number;
  ip: string;
  mask: string;
  mac: string;
}

export interface Route {
  id: string;
  dest: string;      // CIDR
  nextHop: string;   // IP
  iface: number;     // port index
  metric: number;
  connected?: boolean; // true for auto-derived connected routes (unlock-gated)
}

export interface RouterDevice extends DeviceBase {
  kind: 'router';
  interfaces: RouterInterface[];
  routes: Route[];
  usage: Usage;
}

// ─── Switch ─────────────────────────────────────────────────────────────────
// MAC learning is unlock-gated. Without the unlock, the switch floods to all
// ports (works but inefficient). With the unlock, it learns and forwards to
// the correct port only.

export interface SwitchDevice extends DeviceBase {
  kind: 'switch';
  macTable: Record<string, number>;  // MAC → port index
}

// ─── Firewall (realistic, multi-port, zone-based) ──────────────────────────
// Modelled on Cisco ASA: 4 named interfaces with security levels.
// Traffic from higher→lower security is allowed by default; lower→higher
// requires an explicit ACL rule. Each interface has its own IP/mask.

export interface FirewallInterface {
  port: number;
  name: string;             // 'outside' | 'inside' | 'dmz' | custom
  securityLevel: number;    // 0–100 (outside=0, inside=100, dmz=50)
  ip: string;
  mask: string;
  mac: string;
}

export type FwAction   = 'allow' | 'deny';
export type FwProtocol = 'any' | 'tcp' | 'udp' | 'icmp';

export interface FirewallRule {
  id: string;
  action: FwAction;
  protocol: FwProtocol;
  srcZone: string;     // interface name or 'any'
  dstZone: string;     // interface name or 'any'
  src: string;         // 'any' | IP | CIDR
  dst: string;
  ports: string;       // 'any' | '80' | '1000-2000'
  log: boolean;
}

export interface FirewallDevice extends DeviceBase {
  kind: 'firewall';
  interfaces: FirewallInterface[];
  rules: FirewallRule[];
  defaultPolicy: FwAction;   // fallback when no rule matches
  capacityMbps: number;
  usage: Usage;
}

// ─── DDoS Scrubber (anti-DDoS appliance) ────────────────────────────────────
// Transparent inline device: port 0 = upstream, port 1 = downstream.
// Rate-limits or drops traffic per source CIDR. No IP addressing needed.

export interface RateLimit {
  id: string;
  src: string;         // CIDR or 'any'
  maxMbps: number;
  action: 'limit' | 'drop';
  enabled: boolean;
}

export interface DdosScrubberDevice extends DeviceBase {
  kind: 'ddos_scrubber';
  rateLimits: RateLimit[];
  capacityMbps: number;
  synProtection: boolean;
  usage: Usage;
}

// ─── Device union ───────────────────────────────────────────────────────────

export type Device =
  | UplinkDevice
  | ServerDevice
  | RouterDevice
  | SwitchDevice
  | FirewallDevice
  | DdosScrubberDevice;

export type DeviceOf<K extends DeviceKind> = Extract<Device, { kind: K }>;

// ─── Cable ──────────────────────────────────────────────────────────────────

export type CableType = 'ethernet' | 'fibre' | 'crossover';

export interface CableEnd { deviceId: DeviceId; port: number }

export interface Cable {
  id: CableId;
  a: CableEnd;
  b: CableEnd;
  type: CableType;
  bandwidthMbps: number;
  path: Vec2[];    // world px, recomputed whenever devices move
}

// ─── Flow (aggregate traffic stream) ────────────────────────────────────────

export type FlowKind = 'http' | 'dns' | 'auth' | 'attack' | 'probe';

export interface Flow {
  id: FlowId;
  kind: FlowKind;
  origin: 'external' | DeviceId;
  srcCidr: string;               // external flows come from a range
  dstIp: string;
  protocol: 'tcp' | 'udp' | 'icmp';
  dstPort: number;
  rateMbps: number;              // offered load
  serviceId: ServiceId | null;   // legit traffic belongs to a service
  incidentId: IncidentId | null;
}

// ─── Service ────────────────────────────────────────────────────────────────

export interface Service {
  id: ServiceId;
  serverId: DeviceId;
  kind: 'web_static' | 'web_app';
  publicIp: string;              // from uplink block
  demand: number;                // 0.7–1.3, random walk + daily curve
  reputation: number;            // 0.5–2.5
  availability: number;          // 0–1, this tick
  downSinceTick: number | null;
  flowId: FlowId | null;         // the legit traffic flow for this service
}

// ─── Economy ────────────────────────────────────────────────────────────────

export interface Economy {
  balance: number;
  totalEarned: number;
  totalSpent: number;
  revenuePerSec: number;         // display, recomputed each tick
  upkeepPerSec: number;          // display
  repairsCount: number;
  preventiveRepairs: number;
}

// ─── Events & Incidents ─────────────────────────────────────────────────────

export type EventKind = 'hardware_failure' | 'ddos' | 'port_scan';

export interface ScheduledEvent {
  triggerAt: number;             // tick
  kind: EventKind;
  payload: Record<string, unknown>;
}

export type IncidentPhase = 'recon' | 'flood' | 'resolved';

export interface Incident {
  id: IncidentId;
  kind: EventKind;
  phase: IncidentPhase;
  startTick: number;
  endTick: number | null;
  targetDeviceId: DeviceId | null;
  attackFlowIds: FlowId[];
  srcRanges: string[];           // attacker CIDRs
  totalVolumeMbps: number;
  mitigated: boolean;
}

// ─── Unlocks (achievement-gated features) ───────────────────────────────────

export interface Unlocks {
  macLearning: boolean;          // switches auto-learn MACs instead of flooding
  connectedRoutes: boolean;      // routers auto-derive connected routes from interfaces
  serverM: boolean;              // can buy Server M
  serverL: boolean;              // can buy Server L
  advancedFwRules: boolean;      // rate limiting, geo-block in firewall
  upstreamFiltering: boolean;    // block at uplink
  carrierUplink: boolean;        // 10 Gbps uplink tier
  monitoringAgent: boolean;      // predictive health alerts 30 s earlier
}

// ─── Stats (rolling uptime, counters) ───────────────────────────────────────

export interface Stats {
  uptimeBuckets: number[];       // 60 one-minute buckets, each 0–1 availability
  currentBucket: number;         // index into uptimeBuckets
  bucketTickCount: number;       // ticks accumulated in the current bucket
  bucketAvailSum: number;        // sum of per-tick availability in the current bucket
  ddosBlocked: number;
  ddosTotal: number;
  devicesRepaired: number;
  preventiveRepairs: number;
  totalDowntimeTicks: number;
}

// ─── Runtime cache (not saved, rebuilt from state) ──────────────────────────

export interface ResolvedPath {
  hops: { deviceId: DeviceId; inPort: number | null; outPort: number | null; cableId: CableId | null }[];
  blocked: boolean;
  blockedAt: number | null;      // hop index where blocked
  reason: 'fw_deny' | 'no_route' | 'link_down' | 'device_failed' | 'scrubbed' | null;
  ruleId: string | null;
}

export interface Carrier {
  flowId: FlowId;
  kind: FlowKind;
  pathIndex: number;             // current hop along the resolved path
  progress: number;              // 0–1 between current hop and next
  age: number;                   // ticks alive
  size: number;                  // visual radius
}

export interface RuntimeCache {
  paths: Record<FlowId, ResolvedPath>;
  cableLoad: Record<CableId, number>;  // Mbps this tick
  carriers: Carrier[];
  topologyVersion: number;
  topologyDirty: boolean;
}

// ─── Log entry ──────────────────────────────────────────────────────────────

export interface LogEntry {
  tick: number;
  deviceId: DeviceId;
  msg: string;
  level: 'info' | 'warn' | 'alert';
}

// ─── Camera ─────────────────────────────────────────────────────────────────

export interface Camera { x: number; y: number; scale: number }

// ─── World state (saved) ────────────────────────────────────────────────────

export interface WorldState {
  meta: { version: number; seed: number; saveTimestamp: number; playTimeTicks: number };
  camera: Camera;
  speed: 0 | 1 | 2 | 4;                           // 0 = paused
  economy: Economy;
  grid: { width: number; height: number };
  devices: Record<DeviceId, Device>;
  cables: Record<CableId, Cable>;
  flows: Record<FlowId, Flow>;
  services: Record<ServiceId, Service>;
  events: ScheduledEvent[];                         // sorted by triggerAt
  activeIncidents: Record<IncidentId, Incident>;
  unlocks: Unlocks;
  stats: Stats;
  logs: LogEntry[];                                 // last 100 entries
  time: { tick: number };
  nextId: number;
}

// ─── Utility ────────────────────────────────────────────────────────────────

export function assertNever(x: never): never {
  throw new Error(`Unhandled case: ${JSON.stringify(x)}`);
}
// Canvas colours. The DOM UI mirrors these as CSS tokens in index.html.
import type { CableType, DeviceKind } from '../state/types';

export const COLORS = {
  background: 0x0c2240,   // blueprint navy
  gridMinor: 0xbcd6ff,
  gridMajor: 0xbcd6ff,
  card: 0x112c4f,
  label: 0xe4eeff,
  sublabel: 0x8fb4e6,
  selection: 0xffffff,
  hover: 0x8fd3ff,
  invalid: 0xff6b6b,
  led: 0x6dff9c,
  portFree: 0x0c2240,
  portRing: 0xbcd6ff,
  // Phase 2 additions
  healthOk: 0x7fe3a0,
  healthWarn: 0xffc861,
  healthBad: 0xff7a72,
  carrierNormal: 0x5fd0ff,
  carrierAttack: 0xff4444,
} as const;

export const KIND_COLOR: Record<DeviceKind, number> = {
  uplink: 0xc7b8ff,
  server: 0x7fd1ff,
  router: 0xffd27a,
  switch: 0x8fe3a5,
  firewall: 0xff8f86,
  ddos_scrubber: 0xff61d8,
};

export const CABLE_COLOR: Record<CableType, number> = {
  ethernet: 0xb4c2d4,
  fibre: 0xffa94d,
  crossover: 0x5fb8ff,
};
// Procedural device icons (architecture v2, §2). Each kind builds one shared
// GraphicsContext that every instance reuses.
import { GraphicsContext } from 'pixi.js';
import { BODY } from '../balance';
import { assertNever, type DeviceKind } from '../state/types';
import { COLORS, KIND_COLOR } from './palette';

const cache = new Map<string, GraphicsContext>();

function card(ctx: GraphicsContext, color: number): void {
  const h = BODY / 2;
  ctx.roundRect(-h, -h, BODY, BODY, 6).fill({ color: COLORS.card }).stroke({ width: 1.5, color, alpha: 0.55 });
}

function arrowHead(ctx: GraphicsContext, x: number, y: number, dx: number, dy: number, size: number, color: number): void {
  const px = -dy;
  const py = dx;
  ctx.poly([x + dx * size, y + dy * size, x + px * size * 0.8, y + py * size * 0.8, x - px * size * 0.8, y - py * size * 0.8])
    .fill({ color });
}

function drawGlyph(ctx: GraphicsContext, kind: DeviceKind): void {
  const c = KIND_COLOR[kind];
  switch (kind) {
    case 'server': {
      ctx.roundRect(-11, -14, 22, 28, 2.5).fill({ color: c, alpha: 0.16 }).stroke({ width: 2, color: c });
      for (const y of [-7, -1, 5]) ctx.moveTo(-7, y).lineTo(3, y);
      ctx.stroke({ width: 1.6, color: c, alpha: 0.9 });
      ctx.circle(6.5, -7, 1.9).fill({ color: COLORS.led });
      return;
    }
    case 'router': {
      ctx.circle(0, 0, 15).fill({ color: c, alpha: 0.16 }).stroke({ width: 2, color: c });
      for (const [dx, dy] of [[0, -1], [1, 0], [0, 1], [-1, 0]] as const) {
        ctx.moveTo(dx * 3.5, dy * 3.5).lineTo(dx * 8.5, dy * 8.5).stroke({ width: 1.8, color: c });
        arrowHead(ctx, dx * 8.5, dy * 8.5, dx, dy, 3.6, c);
      }
      return;
    }
    case 'switch': {
      ctx.roundRect(-16, -9, 32, 18, 2.5).fill({ color: c, alpha: 0.16 }).stroke({ width: 2, color: c });
      for (let i = 0; i < 6; i++) {
        const x = -10 + i * 4;
        ctx.moveTo(x, -4).lineTo(x, 4);
      }
      ctx.stroke({ width: 1.6, color: c });
      return;
    }
    case 'firewall': {
      ctx.poly([0, -15, 12.5, -10, 11.5, 3, 0, 15, -11.5, 3, -12.5, -10])
        .fill({ color: c, alpha: 0.16 }).stroke({ width: 2, color: c, join: 'round' });
      ctx.moveTo(-11.5, -1).lineTo(11.5, -1).stroke({ width: 2, color: c });
      return;
    }
    case 'uplink': {
      // cloud: stroke the lobes, then cover the inner overlaps with the card colour
      const lobes: [number, number, number][] = [[-8, 1, 6], [0, -4, 8], [8, 1, 6]];
      for (const [x, y, r] of lobes) ctx.circle(x, y, r).stroke({ width: 2, color: c });
      ctx.roundRect(-14, 1, 28, 7, 3.5).stroke({ width: 2, color: c });
      for (const [x, y, r] of lobes) ctx.circle(x, y, r - 1).fill({ color: COLORS.card });
      ctx.roundRect(-13, 2, 26, 5, 2.5).fill({ color: COLORS.card });
      ctx.moveTo(0, -6).lineTo(0, 4).stroke({ width: 2, color: c });
      arrowHead(ctx, 0, 4, 0, 1, 4, c);
      return;
    }
    case 'ddos_scrubber': {
      // Box with filter slits and flow arrows
      ctx.roundRect(-14, -10, 28, 20, 3).fill({ color: c, alpha: 0.16 }).stroke({ width: 2, color: c });
      ctx.moveTo(-8, 0).lineTo(8, 0).stroke({ width: 2, color: c });
      // Vertical filter slits
      ctx.moveTo(-4, -5).lineTo(-4, 5).stroke({ width: 1.5, color: c, alpha: 0.6 });
      ctx.moveTo(4, -5).lineTo(4, 5).stroke({ width: 1.5, color: c, alpha: 0.6 });
      // Input/output dots
      ctx.circle(-8, 0, 2).fill({ color: c });
      ctx.circle(8, 0, 2).fill({ color: c });
      return;
    }
    default:
      assertNever(kind);
  }
}

export function deviceContext(kind: DeviceKind): GraphicsContext {
  let ctx = cache.get(kind);
  if (!ctx) {
    ctx = new GraphicsContext();
    card(ctx, KIND_COLOR[kind]);
    drawGlyph(ctx, kind);
    cache.set(kind, ctx);
  }
  return ctx;
}
// Pixi scene (architecture v2, §2): screen-space grid, then a camera-transformed
// world container holding cables, devices, ports, overlay and placement ghost.
import { Application, Container, Graphics, Text } from 'pixi.js';
import { BODY, CARRIER_MAX_AGE, CELL, HP_CRITICAL, HP_WARNING } from '../balance';
import { portPos, portUsage } from '../state/geometry';
import { assertNever, type Device, type Vec2 } from '../state/types';
import { pointer, runtime, ui, world, deviceAtCell } from '../state/world';
import { deviceContext } from './icons';
import { CABLE_COLOR, COLORS } from './palette';

interface DeviceView {
  root: Container;
  icon: Graphics;
  plate: Graphics; // background behind labels so cables pass under them
  name: Text;
  sub: Text;
}

const LABEL_FONT = '"IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, monospace';

function subLabel(d: Device, usedPorts: Map<string, string>): string {
  switch (d.kind) {
    case 'uplink': return d.publicSubnet;
    case 'server': return d.ip || 'no IP';
    case 'router': {
      const n = d.interfaces.filter((i) => i.ip).length;
      return `${n}/${d.interfaces.length} IPs`;
    }
    case 'switch': {
      const n = d.ports.filter((p) => usedPorts.has(`${d.id}:${p.index}`)).length;
      return `${n}/${d.ports.length} ports`;
    }
    case 'firewall': return `${d.rules.length} rule${d.rules.length === 1 ? '' : 's'}`;
    case 'ddos_scrubber': return `${d.rateLimits.length} limit${d.rateLimits.length === 1 ? '' : 's'}`;
    default: return assertNever(d);
  }
}

export class Renderer {
  readonly app = new Application();
  private grid = new Graphics();
  private worldLayer = new Container();
  private cables = new Graphics();
  private devices = new Container();
  private ports = new Graphics();
  private carriers = new Graphics();
  private healthBadges = new Graphics();
  private overlay = new Graphics();
  private ghost = new Container();
  private ghostIcon = new Graphics();
  private ghostMark = new Graphics();
  private views = new Map<string, DeviceView>();

  async init(host: HTMLElement): Promise<void> {
    await this.app.init({
      resizeTo: host,
      background: COLORS.background,
      antialias: true,
      autoDensity: true,
      resolution: Math.min(window.devicePixelRatio || 1, 2),
      preference: 'webgl',
    });
    host.appendChild(this.app.canvas);
    this.app.canvas.style.touchAction = 'none';
    this.app.stage.addChild(this.grid, this.worldLayer);
    this.worldLayer.addChild(this.cables, this.devices, this.ports, this.carriers, this.healthBadges, this.overlay, this.ghost);
    this.ghost.addChild(this.ghostIcon, this.ghostMark);
    this.ghost.alpha = 0.55;
    this.ghost.visible = false;

    world.subscribe((_s, reason) => {
      this.applyCamera();
      if (reason === 'sim') {
        this.redrawSim();
      } else if (reason !== 'camera') {
        this.redrawWorld();
      }
    });
    ui.subscribe(() => this.redrawInteractive());
    pointer.subscribe(() => this.redrawInteractive());
    this.app.renderer.on('resize', () => this.drawGrid());

    this.applyCamera();
    this.redrawWorld();

    // labels were measured with a fallback font; redo them once web fonts arrive
    document.fonts?.ready.then(() => {
      for (const v of this.views.values()) { v.name.text = ''; v.sub.text = ''; }
      this.redrawWorld();
    }).catch(() => {});
  }

  get canvas(): HTMLCanvasElement {
    return this.app.canvas;
  }

  screenToWorld(sx: number, sy: number): Vec2 {
    const c = world.get().camera;
    return { x: (sx - c.x) / c.scale, y: (sy - c.y) / c.scale };
  }

  get screenSize(): { w: number; h: number } {
    return { w: this.app.screen.width, h: this.app.screen.height };
  }

  private applyCamera(): void {
    const c = world.get().camera;
    this.worldLayer.position.set(c.x, c.y);
    this.worldLayer.scale.set(c.scale);
    const showLabels = c.scale >= 0.45;
    for (const v of this.views.values()) {
      v.name.visible = showLabels;
      v.sub.visible = showLabels;
      v.plate.visible = showLabels;
    }
    this.drawGrid();
  }

  private drawGrid(): void {
    const g = this.grid;
    const { width: w, height: h } = this.app.screen;
    const cam = world.get().camera;
    const cs = CELL * cam.scale;
    g.clear();
    const line = (k: number, vertical: boolean) => {
      if (vertical) {
        const x = Math.round(k * cs + cam.x) + 0.5;
        g.moveTo(x, 0).lineTo(x, h);
      } else {
        const y = Math.round(k * cs + cam.y) + 0.5;
        g.moveTo(0, y).lineTo(w, y);
      }
    };
    const kx0 = Math.ceil(-cam.x / cs);
    const kx1 = Math.floor((w - cam.x) / cs);
    const ky0 = Math.ceil(-cam.y / cs);
    const ky1 = Math.floor((h - cam.y) / cs);
    if (cs >= 9) {
      for (let k = kx0; k <= kx1; k++) if (k % 5 !== 0) line(k, true);
      for (let k = ky0; k <= ky1; k++) if (k % 5 !== 0) line(k, false);
      g.stroke({ width: 1, color: COLORS.gridMinor, alpha: 0.055 });
    }
    if (cs * 5 >= 9) {
      for (let k = Math.ceil(kx0 / 5) * 5; k <= kx1; k += 5) line(k, true);
      for (let k = Math.ceil(ky0 / 5) * 5; k <= ky1; k += 5) line(k, false);
      g.stroke({ width: 1, color: COLORS.gridMajor, alpha: 0.13 });
    }
  }

  private redrawWorld(): void {
    const s = world.get();
    const used = portUsage(s);

    // device views: create, update, remove
    const seen = new Set<string>();
    for (const d of Object.values(s.devices)) {
      seen.add(d.id);
      let v = this.views.get(d.id);
      if (!v) {
        const root = new Container();
        const icon = new Graphics(deviceContext(d.kind));
        const name = new Text({
          text: '', resolution: 3,
          style: { fontFamily: LABEL_FONT, fontSize: 10, fill: COLORS.label, fontWeight: '500' },
        });
        const sub = new Text({
          text: '', resolution: 3,
          style: { fontFamily: LABEL_FONT, fontSize: 8.5, fill: COLORS.sublabel },
        });
        name.anchor.set(0.5, 0);
        sub.anchor.set(0.5, 0);
        name.position.set(0, BODY / 2 + 4);
        sub.position.set(0, BODY / 2 + 17);
        const plate = new Graphics();
        root.addChild(icon, plate, name, sub);
        this.devices.addChild(root);
        v = { root, icon, plate, name, sub };
        this.views.set(d.id, v);
        const show = s.camera.scale >= 0.45;
        name.visible = show;
        sub.visible = show;
        plate.visible = show;
      }
      v.root.position.set((d.gridPos.gx + 0.5) * CELL, (d.gridPos.gy + 0.5) * CELL);
      const sl = subLabel(d, used);
      if (v.name.text !== d.name || v.sub.text !== sl || v.plate.context.instructions.length === 0) {
        v.name.text = d.name;
        v.sub.text = sl;
        const w = Math.max(v.name.width, v.sub.width) + 8;
        v.plate.clear();
        v.plate.roundRect(-w / 2, BODY / 2 + 2, w, 28, 4).fill({ color: COLORS.background, alpha: 0.85 });
      }
    }
    for (const [id, v] of this.views) {
      if (!seen.has(id)) {
        v.root.destroy({ children: true });
        this.views.delete(id);
      }
    }

    this.redrawInteractive();
  }

  /** Cables, ports, selection/hover overlay and ghost: everything that reacts to UI state. */
  private redrawInteractive(): void {
    const s = world.get();
    const u = ui.get();
    const p = pointer.get();
    const used = portUsage(s);
    const cableMode = u.tool.mode === 'cable';

    // cables
    const cg = this.cables;
    cg.clear();
    const selCable = u.selection?.type === 'cable' ? u.selection.id : null;
    for (const c of Object.values(s.cables)) {
      if (c.path.length < 2) continue;
      const pts = c.path;
      const trace = () => {
        cg.moveTo(pts[0]!.x, pts[0]!.y);
        for (let i = 1; i < pts.length; i++) cg.lineTo(pts[i]!.x, pts[i]!.y);
      };
      if (c.id === selCable) {
        trace();
        cg.stroke({ width: 9, color: COLORS.selection, alpha: 0.3, cap: 'round', join: 'round' });
      }
      trace();
      cg.stroke({ width: c.type === 'fibre' ? 3.2 : 2.6, color: CABLE_COLOR[c.type], cap: 'round', join: 'round' });
    }

    // ports
    const pg = this.ports;
    pg.clear();
    for (const d of Object.values(s.devices)) {
      for (const port of d.ports) {
        const pos = portPos(d, port.index);
        const cableId = used.get(`${d.id}:${port.index}`);
        if (cableId) {
          const c = s.cables[cableId];
          pg.circle(pos.x, pos.y, 3.4).fill({ color: c ? CABLE_COLOR[c.type] : COLORS.portRing });
        } else {
          pg.circle(pos.x, pos.y, cableMode ? 4.4 : 3)
            .fill({ color: COLORS.portFree })
            .stroke({ width: 1.3, color: cableMode ? COLORS.hover : COLORS.portRing, alpha: cableMode ? 1 : 0.7 });
        }
      }
    }

    // overlay: hover, selection, pending cable
    const og = this.overlay;
    og.clear();
    const ring = (d: Device, pad: number) => {
      const x = d.gridPos.gx * CELL + (CELL - BODY) / 2 - pad;
      const y = d.gridPos.gy * CELL + (CELL - BODY) / 2 - pad;
      og.roundRect(x, y, BODY + pad * 2, BODY + pad * 2, 7 + pad);
    };
    const hovered = p.hoverDevice ? s.devices[p.hoverDevice] : undefined;
    if (hovered && (u.tool.mode !== 'place')) {
      ring(hovered, 3);
      og.stroke({ width: 1.5, color: COLORS.hover, alpha: 0.6 });
    }
    const selDev = u.selection?.type === 'device' ? s.devices[u.selection.id] : undefined;
    if (selDev) {
      ring(selDev, 4);
      og.stroke({ width: 2, color: COLORS.selection });
    }
    if (u.pendingCable) {
      const d = s.devices[u.pendingCable.deviceId];
      if (d) {
        ring(d, 4);
        og.stroke({ width: 2, color: CABLE_COLOR[u.cableType] });
        const from = u.pendingCable.explicit
          ? portPos(d, u.pendingCable.port)
          : { x: (d.gridPos.gx + 0.5) * CELL, y: (d.gridPos.gy + 0.5) * CELL };
        if (p.pointerWorld) {
          og.moveTo(from.x, from.y).lineTo(p.pointerWorld.x, p.pointerWorld.y)
            .stroke({ width: 2, color: CABLE_COLOR[u.cableType], alpha: 0.6 });
        }
      }
    }

    // ghost: placement preview or drag-move target
    let ghostKind: Device['kind'] | null = null;
    let ghostCell = null as { gx: number; gy: number } | null;
    let ghostOk = true;
    if (u.tool.mode === 'place' && p.hoverCell) {
      ghostKind = u.tool.kind;
      ghostCell = p.hoverCell;
      ghostOk = !deviceAtCell(s, ghostCell.gx, ghostCell.gy);
    } else if (p.dragGhost) {
      const d = s.devices[p.dragGhost.deviceId];
      if (d) {
        ghostKind = d.kind;
        ghostCell = p.dragGhost.cell;
        const other = deviceAtCell(s, ghostCell.gx, ghostCell.gy);
        ghostOk = !other || other.id === d.id;
      }
    }
    if (ghostKind && ghostCell) {
      this.ghost.visible = true;
      this.ghostIcon.context = deviceContext(ghostKind);
      this.ghost.position.set((ghostCell.gx + 0.5) * CELL, (ghostCell.gy + 0.5) * CELL);
      this.ghostMark.clear();
      if (!ghostOk) {
        this.ghostMark.roundRect(-BODY / 2, -BODY / 2, BODY, BODY, 6).fill({ color: COLORS.invalid, alpha: 0.45 });
      }
    } else {
      this.ghost.visible = false;
    }
  }

  /** Redraw carrier particles and health badges — called every sim tick. */
  private redrawSim(): void {
    const s = world.get();
    const cg = this.carriers;
    cg.clear();

    // Carrier particles: visual dots moving along resolved flow paths
    for (const c of runtime.carriers) {
      const path = runtime.paths[c.flowId];
      if (!path || path.hops.length < 2) continue;

      // Find the two hops this carrier is between
      const hopIdx = Math.min(c.pathIndex, path.hops.length - 1);
      const nextIdx = Math.min(hopIdx + 1, path.hops.length - 1);
      if (hopIdx === nextIdx) continue;

      const hopDev = s.devices[path.hops[hopIdx]!.deviceId];
      const nextDev = s.devices[path.hops[nextIdx]!.deviceId];
      if (!hopDev || !nextDev) continue;

      // Interpolate position between device centers
      const ax = (hopDev.gridPos.gx + 0.5) * CELL;
      const ay = (hopDev.gridPos.gy + 0.5) * CELL;
      const bx = (nextDev.gridPos.gx + 0.5) * CELL;
      const by = (nextDev.gridPos.gy + 0.5) * CELL;
      const t = c.progress;
      const px = ax + (bx - ax) * t;
      const py = ay + (by - ay) * t;

      const color = c.kind === 'attack' ? COLORS.carrierAttack : COLORS.carrierNormal;
      const alpha = Math.max(0.2, 1 - c.age / CARRIER_MAX_AGE);
      cg.circle(px, py, c.size).fill({ color, alpha });
    }

    // Health badges: colored indicators on degraded/failed devices
    const hg = this.healthBadges;
    hg.clear();
    for (const d of Object.values(s.devices)) {
      if (d.health.state === 'ok') continue;
      const cx = (d.gridPos.gx + 0.5) * CELL + BODY / 2 - 4;
      const cy = (d.gridPos.gy + 0.5) * CELL - BODY / 2 + 4;
      const hp = d.health.hp;
      const color = hp <= HP_CRITICAL ? COLORS.healthBad
                  : hp <= HP_WARNING  ? COLORS.healthWarn
                  :                     COLORS.healthOk;
      // Outer ring
      hg.circle(cx, cy, 6).fill({ color: COLORS.background, alpha: 0.85 });
      hg.circle(cx, cy, 5).fill({ color });

      // Pulsing effect for failed/critical devices
      if (d.health.state === 'failed' || d.health.state === 'critical') {
        const pulse = 0.3 + 0.3 * Math.sin(Date.now() * 0.005);
        hg.circle(cx, cy, 8).stroke({ width: 1.5, color, alpha: pulse });
      }
    }

    // Also update device sub-labels to reflect health changes
    const used = portUsage(s);
    for (const d of Object.values(s.devices)) {
      const v = this.views.get(d.id);
      if (!v) continue;
      const sl = subLabel(d, used);
      if (v.sub.text !== sl) v.sub.text = sl;
      // Tint device icon based on health
      if (d.health.state === 'failed') {
        v.icon.alpha = 0.4;
      } else if (d.health.state === 'critical' || d.health.state === 'repairing') {
        v.icon.alpha = 0.65;
      } else {
        v.icon.alpha = 1;
      }
    }
  }
}
// Tiny inline replacement for idb-keyval (eliminates npm dependency).
// API-compatible subset: get<T>(key) and set(key, value).

const DB_NAME = 'keyval-store';
const STORE_NAME = 'keyval';

function getDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, 1);
    req.onupgradeneeded = () => {
      req.result.createObjectStore(STORE_NAME);
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function tx(mode: IDBTransactionMode): Promise<IDBObjectStore> {
  return getDB().then((db) => db.transaction(STORE_NAME, mode).objectStore(STORE_NAME));
}

export function get<T = unknown>(key: IDBValidKey): Promise<T | undefined> {
  return tx('readonly').then(
    (store) =>
      new Promise<T | undefined>((resolve, reject) => {
        const req = store.get(key);
        req.onsuccess = () => resolve(req.result as T | undefined);
        req.onerror = () => reject(req.error);
      }),
  );
}

export function set(key: IDBValidKey, value: unknown): Promise<void> {
  return tx('readwrite').then(
    (store) =>
      new Promise<void>((resolve, reject) => {
        const req = store.put(value, key);
        req.onsuccess = () => resolve();
        req.onerror = () => reject(req.error);
      }),
  );
}
// Save / load (architecture v2, §11). Phase 2: migration from v1→v2.
import { START_BALANCE, UPTIME_BUCKETS } from '../balance';
import { get, set } from '../lib/idb-keyval';
import { macFor } from './devices';
import { recomputeAllPaths } from './geometry';
import type { WorldState } from './types';
import { SCHEMA_VERSION, resetRuntime, world } from './world';

const AUTOSAVE_KEY = 'netsim_autosave';

/** MIGRATIONS[v] upgrades a save from version v to v+1. */
const MIGRATIONS: Record<number, (s: any) => any> = {
  // v1→v2: add Phase 2 fields, convert firewall from 2-port to 4-port with interfaces
  1: (s: any) => {
    // Add top-level Phase 2 fields
    s.speed ??= 1;
    s.economy ??= {
      balance: START_BALANCE, totalEarned: 0, totalSpent: 0,
      revenuePerSec: 0, upkeepPerSec: 0, repairsCount: 0, preventiveRepairs: 0,
    };
    s.grid ??= { width: 30, height: 20 };
    s.flows ??= {};
    s.services ??= {};
    s.events ??= [];
    s.activeIncidents ??= {};
    s.unlocks ??= {
      macLearning: false, connectedRoutes: false, serverM: false, serverL: false,
      advancedFwRules: false, upstreamFiltering: false, carrierUplink: false, monitoringAgent: false,
    };
    s.stats ??= {
      uptimeBuckets: new Array(UPTIME_BUCKETS).fill(1), currentBucket: 0,
      bucketTickCount: 0, bucketAvailSum: 0, ddosBlocked: 0, ddosTotal: 0,
      devicesRepaired: 0, preventiveRepairs: 0, totalDowntimeTicks: 0,
    };
    s.logs ??= [];
    s.time ??= { tick: 0 };
    s.meta.playTimeTicks ??= 0;

    // Migrate devices
    for (const d of Object.values(s.devices) as any[]) {
      // Uplink: add uplinkIp and uplinkTier
      if (d.kind === 'uplink') {
        d.uplinkIp ??= '203.0.113.1';
        d.uplinkTier ??= 'basic';
      }
      // Firewall: convert from 2-port simple to 4-port with interfaces
      if (d.kind === 'firewall') {
        if (!d.interfaces) {
          // Old firewalls had 2 ports: outside (0) and inside (1)
          // Add DMZ (2) and spare (3) ports
          while (d.ports.length < 4) {
            const idx = d.ports.length;
            const label = idx === 2 ? 'dmz' : 'spare';
            const portSide = idx === 2 ? 'S' : 'N';
            d.ports.push({ index: idx, side: portSide, offset: 0.5, label, up: true });
          }
          // Create interfaces from ports
          d.interfaces = [
            { port: 0, name: 'outside', securityLevel: 0, ip: '', mask: '255.255.255.0', mac: macFor(d.id, 100) },
            { port: 1, name: 'inside', securityLevel: 100, ip: '', mask: '255.255.255.0', mac: macFor(d.id, 101) },
            { port: 2, name: 'dmz', securityLevel: 50, ip: '', mask: '255.255.255.0', mac: macFor(d.id, 102) },
            { port: 3, name: 'spare', securityLevel: 50, ip: '', mask: '255.255.255.0', mac: macFor(d.id, 103) },
          ];
        }
        // Migrate old rules (no zones) to new format
        for (const r of d.rules ?? []) {
          r.srcZone ??= 'any';
          r.dstZone ??= 'any';
        }
      }
      // Router: add connected flag to routes
      if (d.kind === 'router') {
        for (const rt of d.routes ?? []) {
          rt.connected ??= false;
        }
      }
    }
    return s;
  },
};

export function serialize(state: WorldState): string {
  return JSON.stringify({ ...state, meta: { ...state.meta, saveTimestamp: Date.now() } });
}

export function deserialize(json: string): WorldState | null {
  try {
    let s = JSON.parse(json);
    if (!s || typeof s !== 'object' || !s.meta || !s.devices) return null;
    let v: number = s.meta.version ?? 0;
    while (v < SCHEMA_VERSION) {
      const m = MIGRATIONS[v];
      if (!m) return null;
      s = m(s);
      v++;
      s.meta.version = v;
    }
    if (v > SCHEMA_VERSION) return null; // save from a newer build
    const state = s as WorldState;
    // drop cables that point at missing devices or ports
    for (const c of Object.values(state.cables ?? {})) {
      const ok = [c.a, c.b].every((e) => state.devices[e.deviceId]?.ports[e.port] !== undefined);
      if (!ok) delete state.cables[c.id];
    }
    state.cables ??= {} as any;
    state.camera ??= { x: 0, y: 0, scale: 1 };
    recomputeAllPaths(state);
    resetRuntime();
    return state;
  } catch {
    return null;
  }
}

export async function loadAutosave(): Promise<WorldState | null> {
  try {
    const raw = await get<string>(AUTOSAVE_KEY);
    return raw ? deserialize(raw) : null;
  } catch {
    return null;
  }
}

let saving = false;
export async function saveNow(): Promise<void> {
  if (saving) return;
  saving = true;
  try {
    await set(AUTOSAVE_KEY, serialize(world.get()));
  } catch {
    // storage blocked (private window, preview); the game keeps working without it
  } finally {
    saving = false;
  }
}

/** Save 1 s after the last world change, and every 30 s regardless. */
export function startAutosave(): void {
  let timer: ReturnType<typeof setTimeout> | null = null;
  world.subscribe((_s, reason) => {
    if (reason === 'ui') return;
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => void saveNow(), 1000);
  });
  setInterval(() => void saveNow(), 30_000);
  window.addEventListener('pagehide', () => void saveNow());
}
// Example network shown on first launch: uplink → firewall → router → switch → two servers.
