    { id: `fw_${s.nextId++}`, action: 'allow', protocol: 'tcp', srcZone: 'outside', dstZone: 'inside', src: 'any', dst: 'any', ports: '80', log: false },
    { id: `fw_${s.nextId++}`, action: 'allow', protocol: 'tcp', srcZone: 'outside', dstZone: 'inside', src: 'any', dst: 'any', ports: '443', log: false },
