    fw.interfaces[1]!.ip = '10.0.0.1';
    fw.interfaces[1]!.mask = '255.255.255.0';
  }

  const rt = add('router', 'Core-RT', 7, 4);
  rt.interfaces[3]!.ip = '10.0.0.2';
  rt.interfaces[3]!.mask = '255.255.255.0';
  rt.interfaces[1]!.ip = '192.168.10.1';
  rt.interfaces[1]!.mask = '255.255.255.0';
  rt.routes = [{ id: `rt_${s.nextId++}`, dest: '0.0.0.0/0', nextHop: '10.0.0.1', iface: 3, metric: 1 }];

  const sw = add('switch', 'Rack-SW', 10, 4);
  const web1 = add('server', 'web-01', 9, 7);
  web1.ip = '192.168.10.10';
