  cable(uplink.id, 0, fw.id, 0, 'fibre');
  cable(fw.id, 1, rt.id, 3);
  cable(rt.id, 1, sw.id, 0);
  cable(sw.id, 4, web1.id, 0);
  cable(sw.id, 7, web2.id, 0);
  recomputeAllPaths(s);
  return s;
}
// IPv4 helpers used by config validation now and by the path resolver in Phase 2.

export function parseIp(s: string): number | null {
  const parts = s.trim().split('.');
  if (parts.length !== 4) return null;
  let n = 0;
  for (const p of parts) {
    if (!/^\d{1,3}$/.test(p)) return null;
    const v = Number(p);
    if (v > 255) return null;
    n = n * 256 + v;
  }
  return n >>> 0;
}

export function formatIp(n: number): string {
  return [24, 16, 8, 0].map((sh) => (n >>> sh) & 255).join('.');
}

export function prefixToMask(prefix: number): number {
  return prefix === 0 ? 0 : (0xffffffff << (32 - prefix)) >>> 0;
}

/** Accepts "255.255.255.0", "/24" or "24". Returns prefix length or null. */
export function parseMask(s: string): number | null {
  const t = s.trim();
  const m = /^\/?(\d{1,2})$/.exec(t);
  if (m) {
    const p = Number(m[1]);
    return p <= 32 ? p : null;
  }
  const n = parseIp(t);
  if (n === null) return null;
  // must be contiguous ones followed by zeros
  const inv = ~n >>> 0;
  if ((inv & (inv + 1)) !== 0) return null;
  let p = 0;
  for (let b = 31; b >= 0; b--) if ((n >>> b) & 1) p++;
  return p;
}

export interface Cidr { net: number; prefix: number }

/** Accepts "10.0.0.0/8" or a bare IP (treated as /32). */
export function parseCidr(s: string): Cidr | null {
  const [ip, pre] = s.trim().split('/');
  const n = parseIp(ip ?? '');
  if (n === null) return null;
  if (pre === undefined) return { net: n, prefix: 32 };
  if (!/^\d{1,2}$/.test(pre)) return null;
  const prefix = Number(pre);
  if (prefix > 32) return null;
  return { net: (n & prefixToMask(prefix)) >>> 0, prefix };
}

export function formatCidr(c: Cidr): string {
  return `${formatIp(c.net)}/${c.prefix}`;
}

export function inCidr(ip: number, c: Cidr): boolean {
  const m = prefixToMask(c.prefix);
  return ((ip & m) >>> 0) === c.net;
}

export function isAny(s: string): boolean {
  const t = s.trim().toLowerCase();
  return t === '' || t === 'any' || t === '*';
}

/** 'any' | '80' | '1000-2000' */
export function parsePortRange(s: string): [number, number] | null {
  if (isAny(s)) return [1, 65535];
  const m = /^(\d{1,5})(?:\s*-\s*(\d{1,5}))?$/.exec(s.trim());
  if (!m) return null;
  const a = Number(m[1]);
  const b = m[2] !== undefined ? Number(m[2]) : a;
  if (a < 1 || b > 65535 || a > b) return null;
  return [a, b];
}

/** Network address for an interface, or null if ip/mask are incomplete. */
export function subnetOf(ip: string, mask: string): Cidr | null {
  const n = parseIp(ip);
  const p = parseMask(mask);
  if (n === null || p === null) return null;
  return { net: (n & prefixToMask(p)) >>> 0, prefix: p };
}
// Path resolver (Phase 2): walks the topology from source to destination,
// evaluating L2 forwarding, firewall zone rules, router LPM, and DDoS scrubbing.
// Returns a ResolvedPath describing the hops, whether it's blocked, and why.

import {
  inCidr, isAny, parseCidr, parseIp, parsePortRange,
  subnetOf,
} from '../state/ip';
import type {
  Cable, CableId, DeviceId, DdosScrubberDevice,
  FirewallDevice, FirewallInterface, ResolvedPath,
  RouterDevice, ServerDevice, SwitchDevice,
  WorldState,
} from '../state/types';

// ─── Topology helpers ──────────────────────────────────────────────────────

/** Build a map of "deviceId:port" → { cableId, otherDeviceId, otherPort }. */
interface Link {
  cableId: CableId;
  peerId: DeviceId;
  peerPort: number;
  cable: Cable;
}

function buildLinkMap(state: WorldState): Map<string, Link> {
  const m = new Map<string, Link>();
  for (const c of Object.values(state.cables)) {
    m.set(`${c.a.deviceId}:${c.a.port}`, {
      cableId: c.id, peerId: c.b.deviceId, peerPort: c.b.port, cable: c,
    });
    m.set(`${c.b.deviceId}:${c.b.port}`, {
      cableId: c.id, peerId: c.a.deviceId, peerPort: c.a.port, cable: c,
    });
  }
  return m;
}

/** Follow a cable from a device port, returning what's on the other end. */
export function findPeer(
  links: Map<string, Link>, deviceId: DeviceId, portIndex: number,
): Link | null {
  return links.get(`${deviceId}:${portIndex}`) ?? null;
}

// ─── Firewall evaluation ───────────────────────────────────────────────────

/** Find which firewall interface a port belongs to. */
function fwIfaceForPort(fw: FirewallDevice, port: number): FirewallInterface | undefined {
  return fw.interfaces.find((i) => i.port === port);
}

/** Evaluate firewall rules for a packet traversing from srcIface to dstIface. */
function evaluateFirewall(
  fw: FirewallDevice,
  srcIface: FirewallInterface,
  dstIface: FirewallInterface,
  srcIpNum: number,
  dstIpNum: number,
  protocol: string,
  dstPort: number,
): { allowed: boolean; ruleId: string | null; reason: string } {
  // Zone-based default: higher security → lower security is allowed
  const defaultAllow = srcIface.securityLevel > dstIface.securityLevel;

  // Check explicit ACL rules (first match wins)
  for (const rule of fw.rules) {
    // Zone match
    if (rule.srcZone !== 'any' && rule.srcZone !== srcIface.name) continue;
    if (rule.dstZone !== 'any' && rule.dstZone !== dstIface.name) continue;

    // Protocol match
    if (rule.protocol !== 'any' && rule.protocol !== protocol) continue;

    // Source CIDR match
    if (!isAny(rule.src)) {
      const srcCidr = parseCidr(rule.src);
      if (srcCidr && !inCidr(srcIpNum, srcCidr)) continue;
    }

    // Destination CIDR match
    if (!isAny(rule.dst)) {
      const dstCidr = parseCidr(rule.dst);
      if (dstCidr && !inCidr(dstIpNum, dstCidr)) continue;
    }

    // Port match (only for tcp/udp)
    if (rule.protocol !== 'icmp' && !isAny(rule.ports)) {
      const range = parsePortRange(rule.ports);
      if (range && (dstPort < range[0] || dstPort > range[1])) continue;
    }

    // Rule matched
    return {
      allowed: rule.action === 'allow',
      ruleId: rule.id,
      reason: `firewall ${rule.action} rule "${rule.id}"`,
    };
  }

  // No rule matched — fall through to zone default or policy
  if (defaultAllow) {
    return { allowed: true, ruleId: null, reason: 'zone security level (high→low)' };
  }

  // Fall to default policy
  const allowed = fw.defaultPolicy === 'allow';
  return {
    allowed,
    ruleId: null,
    reason: `firewall default policy: ${fw.defaultPolicy}`,
  };
}

// ─── Router LPM ────────────────────────────────────────────────────────────

/** Longest Prefix Match on a router's routing table. Returns the best route or null. */
function routerLPM(
  router: RouterDevice,
  dstIpNum: number,
  unlockConnected: boolean,
): { route: { dest: string; nextHop: string; iface: number; metric: number } | null } {
  let bestPrefix = -1;
  let bestMetric = Infinity;
  let bestRoute: { dest: string; nextHop: string; iface: number; metric: number } | null = null;

  // Static routes
  for (const rt of router.routes) {
    if (rt.connected && !unlockConnected) continue; // skip auto-derived if not unlocked
    const cidr = parseCidr(rt.dest);
    if (!cidr) continue;
    if (!inCidr(dstIpNum, cidr)) continue;
    if (cidr.prefix > bestPrefix || (cidr.prefix === bestPrefix && rt.metric < bestMetric)) {
      bestPrefix = cidr.prefix;
      bestMetric = rt.metric;
      bestRoute = rt;
    }
  }

  // Connected routes (auto-derived from interface IPs) — only if unlocked
  if (unlockConnected) {
    for (const iface of router.interfaces) {
      const net = subnetOf(iface.ip, iface.mask);
      if (!net) continue;
      if (!inCidr(dstIpNum, net)) continue;
      if (net.prefix > bestPrefix || (net.prefix === bestPrefix && 0 < bestMetric)) {
        bestPrefix = net.prefix;
        bestMetric = 0;
        bestRoute = { dest: `${iface.ip}/${net.prefix}`, nextHop: '', iface: iface.port, metric: 0 };
      }
    }
  }

  return { route: bestRoute };
}

// ─── DDoS scrubber evaluation ──────────────────────────────────────────────

interface ScrubResult {
  passed: boolean;
  limitedMbps: number | null; // null if not rate-limited
}

function evaluateScrubber(
  device: DdosScrubberDevice,
  srcIpNum: number,
  bandwidthMbps: number,
): ScrubResult {
  if (!device.synProtection && device.rateLimits.length === 0) {
    return { passed: true, limitedMbps: null };
  }

  for (const rl of device.rateLimits) {
    if (!rl.enabled) continue;

    // Check source match
    if (!isAny(rl.src)) {
      const cidr = parseCidr(rl.src);
      if (cidr && !inCidr(srcIpNum, cidr)) continue;
    }

    // Source matches — apply the rule
    if (bandwidthMbps > rl.maxMbps) {
      if (rl.action === 'drop') {
        return { passed: false, limitedMbps: null };
      }
      // 'limit' — let it through at reduced rate
      return { passed: true, limitedMbps: rl.maxMbps };
    }
  }

  return { passed: true, limitedMbps: null };
}

// ─── Main path resolution ──────────────────────────────────────────────────

type Hop = ResolvedPath['hops'][number];

const MAX_HOPS = 32; // prevent infinite loops

/**
 * Resolve the network path from a device out toward a destination IP.
 * Walks cable→device→cable until it reaches the uplink (outbound) or
 * a server (inbound).
 */
export function resolvePath(
  state: WorldState,
  srcDeviceId: DeviceId,
  outPort: number,
  dstIpNum: number,
  srcIpNum: number,
  protocol: string,
  dstPort: number,
  bandwidthMbps: number,
): ResolvedPath {
  const links = buildLinkMap(state);
  const hops: Hop[] = [];
  const result: ResolvedPath = {
    hops,
    blocked: false,
    blockedAt: null,
    reason: null,
    ruleId: null,
  };

  // Start: the source device itself
  hops.push({ deviceId: srcDeviceId, inPort: null, outPort, cableId: null });

  let currentDeviceId = srcDeviceId;
  let currentOutPort = outPort;

  for (let step = 0; step < MAX_HOPS; step++) {
    // Follow the cable from current device's output port
    const link = findPeer(links, currentDeviceId, currentOutPort);
    if (!link) {
      // No cable connected — dead end
      result.blocked = true;
      result.blockedAt = hops.length - 1;
      result.reason = 'link_down';
      return result;
    }

    // Update previous hop's cableId
    hops[hops.length - 1]!.cableId = link.cableId;

    const nextDevice = state.devices[link.peerId];
    if (!nextDevice) {
      result.blocked = true;
      result.blockedAt = hops.length - 1;
      result.reason = 'link_down';
      return result;
    }

    // Check if the device or the incoming port is down
    if (nextDevice.health.state === 'failed') {
      hops.push({ deviceId: nextDevice.id, inPort: link.peerPort, outPort: null, cableId: null });
      result.blocked = true;
      result.blockedAt = hops.length - 1;
      result.reason = 'device_failed';
      return result;
    }

    if (!nextDevice.ports[link.peerPort]?.up) {
      hops.push({ deviceId: nextDevice.id, inPort: link.peerPort, outPort: null, cableId: null });
      result.blocked = true;
      result.blockedAt = hops.length - 1;
      result.reason = 'link_down';
      return result;
    }

    // Process the next device based on its kind
    switch (nextDevice.kind) {
      case 'uplink': {
        // Reached the internet — path complete (outbound)
        hops.push({ deviceId: nextDevice.id, inPort: link.peerPort, outPort: null, cableId: null });
        return result;
      }

      case 'server': {
        // Reached a server — path complete (inbound)
        hops.push({ deviceId: nextDevice.id, inPort: link.peerPort, outPort: null, cableId: null });
        return result;
      }

      case 'switch': {
        // L2 forwarding
        const outPortIdx = switchForward(state, nextDevice, link.peerPort, dstIpNum, links);
        if (outPortIdx === null) {
          // Can't forward — no link to destination
          hops.push({ deviceId: nextDevice.id, inPort: link.peerPort, outPort: null, cableId: null });
          result.blocked = true;
          result.blockedAt = hops.length - 1;
          result.reason = 'link_down';
          return result;
        }
        hops.push({ deviceId: nextDevice.id, inPort: link.peerPort, outPort: outPortIdx, cableId: null });
        currentDeviceId = nextDevice.id;
        currentOutPort = outPortIdx;
        break;
      }

      case 'router': {
        // L3 routing — LPM lookup
        const lpm = routerLPM(nextDevice, dstIpNum, state.unlocks.connectedRoutes);
        if (!lpm.route) {
          hops.push({ deviceId: nextDevice.id, inPort: link.peerPort, outPort: null, cableId: null });
          result.blocked = true;
          result.blockedAt = hops.length - 1;
          result.reason = 'no_route';
          return result;
        }
        hops.push({ deviceId: nextDevice.id, inPort: link.peerPort, outPort: lpm.route.iface, cableId: null });
        currentDeviceId = nextDevice.id;
        currentOutPort = lpm.route.iface;
        break;
      }

      case 'firewall': {
        // Zone-based firewall evaluation
        const inIface = fwIfaceForPort(nextDevice, link.peerPort);
        if (!inIface) {
          // Port not configured as a firewall interface — pass through (shouldn't happen)
          hops.push({ deviceId: nextDevice.id, inPort: link.peerPort, outPort: null, cableId: null });
          result.blocked = true;
          result.blockedAt = hops.length - 1;
          result.reason = 'link_down';
          return result;
        }

        // Find the egress interface — pick the one with a route toward dstIp,
        // or the first interface that isn't the ingress
        const egressIface = findFirewallEgress(nextDevice, link.peerPort, dstIpNum);
        if (!egressIface) {
          hops.push({ deviceId: nextDevice.id, inPort: link.peerPort, outPort: null, cableId: null });
          result.blocked = true;
          result.blockedAt = hops.length - 1;
          result.reason = 'no_route';
          return result;
        }

        const fwResult = evaluateFirewall(
          nextDevice, inIface, egressIface,
          srcIpNum, dstIpNum, protocol, dstPort,
        );

        if (!fwResult.allowed) {
          hops.push({ deviceId: nextDevice.id, inPort: link.peerPort, outPort: egressIface.port, cableId: null });
          result.blocked = true;
          result.blockedAt = hops.length - 1;
          result.reason = 'fw_deny';
          result.ruleId = fwResult.ruleId;
          return result;
        }

        hops.push({ deviceId: nextDevice.id, inPort: link.peerPort, outPort: egressIface.port, cableId: null });
        currentDeviceId = nextDevice.id;
        currentOutPort = egressIface.port;
        break;
      }

      case 'ddos_scrubber': {
        // Inline scrubber — port 0 = upstream, port 1 = downstream
        // Traffic passes through: in on one port, out the other
        const outPortIdx = link.peerPort === 0 ? 1 : 0;

        const scrubResult = evaluateScrubber(nextDevice, srcIpNum, bandwidthMbps);
        if (!scrubResult.passed) {
          hops.push({ deviceId: nextDevice.id, inPort: link.peerPort, outPort: outPortIdx, cableId: null });
          result.blocked = true;
          result.blockedAt = hops.length - 1;
          result.reason = 'scrubbed';
          return result;
        }

        hops.push({ deviceId: nextDevice.id, inPort: link.peerPort, outPort: outPortIdx, cableId: null });
        currentDeviceId = nextDevice.id;
        currentOutPort = outPortIdx;
        break;
      }

      default:
        // Shouldn't reach here — exhaustive check
        void (nextDevice satisfies never);
        result.blocked = true;
        result.blockedAt = hops.length - 1;
        result.reason = 'link_down';
        return result;
    }
  }

  // Max hops reached — probably a loop
  result.blocked = true;
  result.blockedAt = hops.length - 1;
  result.reason = 'no_route';
  return result;
}

// ─── Switch forwarding ─────────────────────────────────────────────────────

/**
 * Decide which port a switch should forward a frame out of.
 * Without MAC learning unlocked, floods to the first connected port that isn't
 * the ingress (hub behavior). With MAC learning, checks the MAC table.
 */
function switchForward(
  state: WorldState,
  sw: SwitchDevice,
  inPort: number,
  _dstIpNum: number,
  links: Map<string, Link>,
): number | null {
  // With MAC learning, we'd look up the destination MAC. But the simulation
  // uses IP-level flows, so we need to find which port leads toward the
  // destination. For a switch, all ports are on the same L2 segment.
  // We find the first connected port (that isn't the ingress).

  if (state.unlocks.macLearning) {
    // MAC learning enabled: check the table for the destination.
    // Since we work at the IP level, we check which connected devices
    // have the target IP and forward there. Fall back to flooding.
    // (In a real network this would use ARP + MAC tables, but our sim
    // abstracts that to "the switch knows which port leads to which IP".)
    // For simplicity, flood to all connected ports except ingress.
  }

  // Hub/flooding behavior: pick the first connected port that isn't the ingress
  for (const port of sw.ports) {
    if (port.index === inPort) continue;
    if (!port.up) continue;
    const link = links.get(`${sw.id}:${port.index}`);
    if (link) return port.index;
  }

  return null; // no other connected ports
}

// ─── Firewall egress selection ─────────────────────────────────────────────

/** Find the egress firewall interface for traffic going toward dstIp. */
function findFirewallEgress(
  fw: FirewallDevice,
  inPort: number,
  dstIpNum: number,
): FirewallInterface | null {
  // First: check if any interface's subnet contains the destination
  for (const iface of fw.interfaces) {
    if (iface.port === inPort) continue;
    const net = subnetOf(iface.ip, iface.mask);
    if (net && inCidr(dstIpNum, net)) return iface;
  }

  // Second: pick the interface with the lowest security level (toward outside)
  // if traffic is heading outbound, or highest (toward inside) if inbound.
  // Simple heuristic: just pick the first interface that isn't the ingress.
  const inIface = fw.interfaces.find((i) => i.port === inPort);
  if (!inIface) return null;

  // If coming from inside (high security), go to the lowest security interface
  // If coming from outside (low security), go to the highest security interface
  let best: FirewallInterface | null = null;
  for (const iface of fw.interfaces) {
    if (iface.port === inPort) continue;
    if (!fw.ports[iface.port]?.up) continue;
    if (!best) {
      best = iface;
      continue;
    }
    if (inIface.securityLevel >= 50) {
      // Coming from inside/DMZ — go toward lower security (outside)
      if (iface.securityLevel < best.securityLevel) best = iface;
    } else {
      // Coming from outside — go toward higher security (inside)
      if (iface.securityLevel > best.securityLevel) best = iface;
    }
  }

  return best;
}

// ─── Inbound path resolution ───────────────────────────────────────────────

/**
 * Resolve an inbound path from the internet to a destination IP.
 * Starts at the uplink device and walks inward through the topology.
 */
export function resolveInbound(
  state: WorldState,
  dstIpNum: number,
  srcIpNum: number,
  protocol: string,
  dstPort: number,
  bandwidthMbps: number,
): ResolvedPath {
  // Find the uplink device
  const uplink = Object.values(state.devices).find((d) => d.kind === 'uplink');
  if (!uplink) {
    return {
      hops: [],
      blocked: true,
      blockedAt: null,
      reason: 'link_down',
      ruleId: null,
    };
  }

  // Start from uplink's first port (the WAN port)
  return resolvePath(state, uplink.id, 0, dstIpNum, srcIpNum, protocol, dstPort, bandwidthMbps);
}

// ─── Find server by IP ─────────────────────────────────────────────────────

/** Find a server device by its configured IP address. */
export function findServerByIp(state: WorldState, ipNum: number): ServerDevice | null {
  for (const d of Object.values(state.devices)) {
    if (d.kind === 'server') {
      const srvIp = parseIp(d.ip);
      if (srvIp === ipNum) return d;
    }
  }
  return null;
}

/** Find which port on a server has a cable attached. */
export function findServerPort(state: WorldState, server: ServerDevice): number {
  const links = buildLinkMap(state);
  for (const port of server.ports) {
    if (links.has(`${server.id}:${port.index}`)) return port.index;
  }
  return 0;
}
// Flow management (Phase 2): creates, updates, and removes aggregate traffic
// streams. Service flows represent legitimate customer traffic. Attack flows
// represent DDoS incidents. Each flow is resolved through the path resolver
// every time the topology changes.

import { parseIp } from '../state/ip';
import { resolveInbound, resolvePath } from './path';
import type {
  DeviceId, Flow, FlowId, IncidentId, ResolvedPath,
  RuntimeCache, Service, WorldState,
} from '../state/types';

// ─── Id generation ─────────────────────────────────────────────────────────

function nextFlowId(state: WorldState): FlowId {
  const id = `flw_${state.nextId}`;
  state.nextId++;
  return id;
}

// ─── Service flow management ───────────────────────────────────────────────

/** Base rate for a web_static service in Mbps. */
const BASE_SERVICE_MBPS = 2;

/**
 * Create or update the legitimate traffic flow for a service.
 * The flow comes from "the internet" toward the service's public IP.
 */
export function ensureServiceFlow(state: WorldState, svc: Service, cache: RuntimeCache): void {
  // Compute offered rate from demand and reputation
  const rateMbps = BASE_SERVICE_MBPS * svc.demand * svc.reputation;

  if (svc.flowId && state.flows[svc.flowId]) {
    // Update existing flow
    const flow = state.flows[svc.flowId];
    flow.rateMbps = rateMbps;
  } else {
    // Create new flow
    const id = nextFlowId(state);
    const flow: Flow = {
      id,
      kind: 'http',
      origin: 'external',
      srcCidr: '0.0.0.0/0',
      dstIp: svc.publicIp,
      protocol: 'tcp',
      dstPort: 80,
      rateMbps,
      serviceId: svc.id,
      incidentId: null,
    };
    state.flows[id] = flow;
    svc.flowId = id;
  }

  // Resolve the path for this flow
  resolveFlowPath(state, state.flows[svc.flowId!]!, cache);
}

/**
 * Remove the flow associated with a service.
 */
export function removeServiceFlow(state: WorldState, svc: Service, cache: RuntimeCache): void {
  if (svc.flowId) {
    delete state.flows[svc.flowId];
    delete cache.paths[svc.flowId];
    svc.flowId = null;
  }
}

// ─── Attack flow management ────────────────────────────────────────────────

/**
 * Create attack flows for a DDoS incident.
 * Returns the IDs of the created flows.
 */
export function createAttackFlows(
  state: WorldState,
  cache: RuntimeCache,
  targetIp: string,
  srcRanges: string[],
  totalVolumeMbps: number,
  incidentId: IncidentId,
): FlowId[] {
  const flowIds: FlowId[] = [];
  const perRange = totalVolumeMbps / Math.max(srcRanges.length, 1);

  for (const srcCidr of srcRanges) {
    const id = nextFlowId(state);
    const flow: Flow = {
      id,
      kind: 'attack',
      origin: 'external',
      srcCidr,
      dstIp: targetIp,
      protocol: 'tcp',
      dstPort: 80, // HTTP flood by default
      rateMbps: perRange,
      serviceId: null,
      incidentId,
    };
    state.flows[id] = flow;
    flowIds.push(id);
    resolveFlowPath(state, flow, cache);
  }

  return flowIds;
}

/**
 * Remove all flows belonging to an incident.
 */
export function removeIncidentFlows(
  state: WorldState,
  cache: RuntimeCache,
  flowIds: FlowId[],
): void {
  for (const id of flowIds) {
    delete state.flows[id];
    delete cache.paths[id];
  }
}

// ─── Path resolution ───────────────────────────────────────────────────────

/**
 * Resolve (or re-resolve) the path for a single flow and cache it.
 */
export function resolveFlowPath(
  state: WorldState,
  flow: Flow,
  cache: RuntimeCache,
): ResolvedPath {
  const dstIpNum = parseIp(flow.dstIp) ?? 0;

  // Pick a representative source IP from the CIDR (first host)
  const srcIpNum = parseSrcIp(flow.srcCidr) ?? 0;

  let path: ResolvedPath;

  if (flow.origin === 'external') {
    // Inbound: from internet through uplink toward destination
    path = resolveInbound(
      state, dstIpNum, srcIpNum,
      flow.protocol, flow.dstPort, flow.rateMbps,
    );
  } else {
    // Outbound from a specific device
    const srcDevice = state.devices[flow.origin];
    if (!srcDevice) {
      path = { hops: [], blocked: true, blockedAt: null, reason: 'link_down', ruleId: null };
    } else {
      const outPort = findDevicePort(state, flow.origin);
      path = resolvePath(
        state, flow.origin, outPort,
        dstIpNum, srcIpNum, flow.protocol, flow.dstPort, flow.rateMbps,
      );
    }
  }

  cache.paths[flow.id] = path;
  return path;
}

/**
 * Re-resolve all flow paths (called when topology changes).
 */
export function resolveAllFlowPaths(state: WorldState, cache: RuntimeCache): void {
  for (const flow of Object.values(state.flows)) {
    resolveFlowPath(state, flow, cache);
  }
  cache.topologyDirty = false;
}

// ─── Bandwidth aggregation ─────────────────────────────────────────────────

/**
 * Aggregate bandwidth on each cable from all active flows.
 * Returns load per cable in Mbps.
 */
export function aggregateBandwidth(
  state: WorldState,
  cache: RuntimeCache,
): void {
  // Reset cable loads
  const cableLoad: Record<string, number> = {};

  for (const flow of Object.values(state.flows)) {
    const path = cache.paths[flow.id];
    if (!path || path.blocked) continue;

    // Walk the hops and add bandwidth to each cable traversed
    for (const hop of path.hops) {
      if (hop.cableId) {
        cableLoad[hop.cableId] = (cableLoad[hop.cableId] ?? 0) + flow.rateMbps;
      }
    }
  }

  cache.cableLoad = cableLoad;
}

/**
 * Compute availability for each service based on path reachability
 * and server health.
 */
export function computeServiceAvailability(
  state: WorldState,
  cache: RuntimeCache,
): void {
  for (const svc of Object.values(state.services)) {
    const server = state.devices[svc.serverId];
    if (!server || server.health.state === 'failed') {
      svc.availability = 0;
      if (!svc.downSinceTick) svc.downSinceTick = state.time.tick;
      continue;
    }

    // Check if the service flow's path is blocked
    if (svc.flowId) {
      const path = cache.paths[svc.flowId];
      if (!path || path.blocked) {
        svc.availability = 0;
        if (!svc.downSinceTick) svc.downSinceTick = state.time.tick;
        continue;
      }
    }

    // Check server overload — bandwidth usage > 1.0 means saturated
    if (server.kind === 'server' && server.usage.bandwidth > 1.0) {
      // Partial availability when overloaded
      svc.availability = Math.max(0, 1 - (server.usage.bandwidth - 1));
    } else {
      svc.availability = 1;
    }

    if (svc.availability > 0) {
      svc.downSinceTick = null;
    }
  }
}

// ─── Service demand simulation ─────────────────────────────────────────────

/**
 * Update service demand with a gentle random walk.
 * Called once per tick.
 */
export function updateServiceDemand(state: WorldState): void {
  for (const svc of Object.values(state.services)) {
    // Random walk: ±0.5% per tick, clamped to 0.5–1.5
    const delta = (Math.random() - 0.5) * 0.01;
    svc.demand = Math.max(0.5, Math.min(1.5, svc.demand + delta));

    // Reputation drifts based on availability
    if (svc.availability >= 0.99) {
      svc.reputation = Math.min(2.5, svc.reputation + 0.0002);
    } else if (svc.availability < 0.5) {
      svc.reputation = Math.max(0.5, svc.reputation - 0.001);
    }
  }
}

// ─── Helpers ───────────────────────────────────────────────────────────────

/** Parse the first host IP from a CIDR range for use as representative source. */
function parseSrcIp(cidr: string): number {
  if (cidr === '0.0.0.0/0' || cidr === 'any') {
    // External internet traffic — use a generic external IP
    return parseIp('198.51.100.1') ?? 0;
  }
  const slash = cidr.indexOf('/');
  const ip = slash >= 0 ? cidr.slice(0, slash) : cidr;
  return parseIp(ip) ?? 0;
}

/** Find the first connected port on a device. */
function findDevicePort(state: WorldState, deviceId: DeviceId): number {
  const device = state.devices[deviceId];
  if (!device) return 0;

  // Check cables for connected ports
  for (const cable of Object.values(state.cables)) {
    if (cable.a.deviceId === deviceId) return cable.a.port;
    if (cable.b.deviceId === deviceId) return cable.b.port;
  }
  return 0;
}
// Simulation engine (Phase 2): 20-tps fixed-timestep tick pipeline.
// Each tick: advance time → fire scheduled events → update flows/paths →
// economy → health degradation/repair → stats → spawn carrier particles.

import {
  CARRIER_MAX_AGE, DEVICE_UPKEEP, REPAIR_COST_FULL, REPAIR_COST_PREVENTIVE,
  REPAIR_DURATION_FULL, REPAIR_DURATION_PREVENTIVE, TICKS_PER_SEC,
} from '../balance';
import type {
  Carrier, DeviceId,
  EventKind, FaultMode, Incident, IncidentId,
  RuntimeCache, ScheduledEvent,
  WorldState,
} from '../state/types';
import {
  aggregateBandwidth,
  computeServiceAvailability,
  createAttackFlows,
  ensureServiceFlow,
  removeIncidentFlows,
  resolveAllFlowPaths,
  updateServiceDemand,
} from './flows';

// ─── Constants ─────────────────────────────────────────────────────────────

/** Seconds per in-game minute (at 1× speed). */
const GAME_MINUTE_TICKS = 60 * TICKS_PER_SEC; // 1200 ticks = 1 game minute

/** Revenue per service unit per tick at 1× speed. */
const REVENUE_PER_TICK = 0.05;

/** Maximum log entries kept. */
const MAX_LOGS = 100;

/** Carrier particle spawn interval in ticks (per flow). */
const CARRIER_SPAWN_INTERVAL = Math.round(TICKS_PER_SEC / 5); // ~5 carriers/s per flow

/** Maximum carrier particles alive. */
const MAX_CARRIERS = 200;

// ─── Runtime cache factory ─────────────────────────────────────────────────

export function createCache(): RuntimeCache {
  return {
    paths: {},
    cableLoad: {},
    carriers: [],
    topologyVersion: 0,
    topologyDirty: true,
  };
}

// ─── Main tick ─────────────────────────────────────────────────────────────

/**
 * Run one simulation tick. Mutates state in place.
 * Returns true if something interesting happened (for UI hints).
 */
export function tick(state: WorldState, cache: RuntimeCache): boolean {
  if (state.speed === 0) return false; // paused

  let interesting = false;
  const ticksToRun = state.speed; // 1, 2, or 4 ticks per frame-tick

  for (let i = 0; i < ticksToRun; i++) {
    state.time.tick++;
    state.meta.playTimeTicks++;

    // 1. Fire scheduled events
    if (fireEvents(state, cache)) interesting = true;

    // 2. Update active incidents
    if (updateIncidents(state, cache)) interesting = true;

    // 3. Resolve paths if topology changed
    if (cache.topologyDirty) {
      resolveAllFlowPaths(state, cache);
    }

    // 4. Update service demand
    updateServiceDemand(state);

    // 5. Ensure service flows exist and are updated
    for (const svc of Object.values(state.services)) {
      ensureServiceFlow(state, svc, cache);
    }

    // 6. Aggregate bandwidth
    aggregateBandwidth(state, cache);

    // 7. Compute device usage from flows
    computeDeviceUsage(state, cache);

    // 8. Compute service availability
    computeServiceAvailability(state, cache);

    // 9. Economy
    tickEconomy(state);

    // 10. Health degradation and repair
    if (tickHealth(state, cache)) interesting = true;

    // 11. Stats
    tickStats(state);

    // 12. Schedule next events if queue is getting low
    if (state.events.length < 3) {
      scheduleRandomEvent(state);
    }
  }

  // 13. Carrier particles (visual, once per frame regardless of speed)
  tickCarriers(state, cache);

  return interesting;
}

// ─── Event scheduling & firing ─────────────────────────────────────────────

function fireEvents(state: WorldState, cache: RuntimeCache): boolean {
  let fired = false;
  while (state.events.length > 0 && state.events[0]!.triggerAt <= state.time.tick) {
    const event = state.events.shift()!;
    handleEvent(state, cache, event);
    fired = true;
  }
  return fired;
}

function handleEvent(state: WorldState, cache: RuntimeCache, event: ScheduledEvent): void {
  switch (event.kind) {
    case 'hardware_failure':
      handleHardwareFailure(state, cache, event);
      break;
    case 'ddos':
      handleDdosStart(state, cache, event);
      break;
    case 'port_scan':
      handlePortScan(state, event);
      break;
  }
}

function handleHardwareFailure(state: WorldState, cache: RuntimeCache, _event: ScheduledEvent): void {
  // Pick a random non-uplink device
  const devices = Object.values(state.devices).filter((d) => d.kind !== 'uplink');
  if (devices.length === 0) return;

  const target = devices[Math.floor(Math.random() * devices.length)]!;
  const faults: FaultMode[] = ['disk', 'nic', 'overheat', 'board'];
  const fault = faults[Math.floor(Math.random() * faults.length)]!;

  // Start degradation
  target.health.fault = fault;
  target.health.degradeRatePerTick = 0.15 + Math.random() * 0.2; // 0.15–0.35 HP/tick
  target.health.state = 'degrading';

  // If NIC fault, kill a random port
  if (fault === 'nic') {
    const upPorts = target.ports.filter((p) => p.up);
    if (upPorts.length > 0) {
      const p = upPorts[Math.floor(Math.random() * upPorts.length)]!;
      p.up = false;
      target.health.faultPort = p.index;
      cache.topologyDirty = true;
    }
  }

  addLog(state, target.id, `Hardware failure: ${fault}`, 'alert');
}

function handleDdosStart(state: WorldState, _cache: RuntimeCache, _event: ScheduledEvent): void {
  // Find a service to target
  const services = Object.values(state.services);
  if (services.length === 0) return;

  const targetSvc = services[Math.floor(Math.random() * services.length)]!;
  const incId = `inc_${state.nextId++}` as IncidentId;

  // Generate 2–5 attacker source ranges
  const numRanges = 2 + Math.floor(Math.random() * 4);
  const srcRanges: string[] = [];
  for (let i = 0; i < numRanges; i++) {
    const a = Math.floor(Math.random() * 223) + 1;
    const b = Math.floor(Math.random() * 256);
    srcRanges.push(`${a}.${b}.0.0/16`);
  }

  // Volume scales with game time — starts small, grows over time
  const baseVolume = 50; // Mbps
  const timeScale = 1 + Math.floor(state.meta.playTimeTicks / (GAME_MINUTE_TICKS * 5));
  const totalVolume = baseVolume * timeScale * (0.8 + Math.random() * 0.4);

  // Create the incident (starts in recon phase)
  const incident: Incident = {
    id: incId,
    kind: 'ddos',
    phase: 'recon',
    startTick: state.time.tick,
    endTick: null,
    targetDeviceId: targetSvc.serverId,
    attackFlowIds: [],
    srcRanges,
    totalVolumeMbps: totalVolume,
    mitigated: false,
  };

  state.activeIncidents[incId] = incident;
  state.stats.ddosTotal++;

  addLog(state, targetSvc.serverId, `DDoS recon detected from ${numRanges} sources`, 'warn');
}

function handlePortScan(state: WorldState, _event: ScheduledEvent): void {
  // Log a port scan event — mostly informational
  const devices = Object.values(state.devices).filter((d) => d.kind === 'firewall');
  if (devices.length === 0) return;

  const fw = devices[Math.floor(Math.random() * devices.length)]!;
  addLog(state, fw.id, 'Port scan detected on outside interface', 'warn');
}

// ─── Incident lifecycle ────────────────────────────────────────────────────

function updateIncidents(state: WorldState, cache: RuntimeCache): boolean {
  let changed = false;

  for (const incident of Object.values(state.activeIncidents)) {
    if (incident.kind !== 'ddos') continue;

    const age = state.time.tick - incident.startTick;

    switch (incident.phase) {
      case 'recon': {
        // Recon lasts 5–10 seconds (100–200 ticks)
        const reconDuration = 100 + Math.floor(Math.random() * 100);
        if (age >= reconDuration) {
          // Transition to flood phase
          incident.phase = 'flood';

          // Find the target service's public IP
          const svc = Object.values(state.services).find(
            (s) => s.serverId === incident.targetDeviceId,
          );
          const targetIp = svc?.publicIp ?? '203.0.113.1';

          // Create attack flows
          incident.attackFlowIds = createAttackFlows(
            state, cache,
            targetIp,
            incident.srcRanges,
            incident.totalVolumeMbps,
            incident.id,
          );

          addLog(
            state,
            incident.targetDeviceId ?? '' as DeviceId,
            `DDoS flood started: ${incident.totalVolumeMbps.toFixed(0)} Mbps from ${incident.srcRanges.length} ranges`,
            'alert',
          );
          changed = true;
        }
        break;
      }

      case 'flood': {
        // Check if all attack flows are blocked (mitigated)
        const allBlocked = incident.attackFlowIds.every((fid) => {
          const path = cache.paths[fid];
          return path?.blocked === true;
        });

        if (allBlocked && !incident.mitigated) {
          incident.mitigated = true;
          state.stats.ddosBlocked++;
          addLog(
            state,
            incident.targetDeviceId ?? '' as DeviceId,
            'DDoS attack mitigated',
            'info',
          );
        }

        // DDoS ends after 30–120 seconds (600–2400 ticks)
        const floodStart = incident.startTick + 150; // approx recon duration
        const floodDuration = 600 + Math.floor(Math.random() * 1800);
        if (state.time.tick - floodStart >= floodDuration) {
          // Resolve the incident
          incident.phase = 'resolved';
          incident.endTick = state.time.tick;
          removeIncidentFlows(state, cache, incident.attackFlowIds);
          addLog(
            state,
            incident.targetDeviceId ?? '' as DeviceId,
            'DDoS attack ended',
            'info',
          );
          changed = true;
        }
        break;
      }

      case 'resolved': {
        // Clean up resolved incidents after a while
        if (incident.endTick && state.time.tick - incident.endTick > TICKS_PER_SEC * 30) {
          delete state.activeIncidents[incident.id];
        }
        break;
      }
    }
  }

  return changed;
}

// ─── Economy ───────────────────────────────────────────────────────────────

function tickEconomy(state: WorldState): void {
  let revenue = 0;
  let upkeep = 0;

  // Revenue from services
  for (const svc of Object.values(state.services)) {
    if (svc.availability > 0) {
      const svcRevenue = REVENUE_PER_TICK * svc.demand * svc.reputation * svc.availability;
      revenue += svcRevenue;
    }
  }

  // Upkeep from devices
  for (const dev of Object.values(state.devices)) {
    const rate = DEVICE_UPKEEP[dev.kind] ?? 0;
    upkeep += rate;
  }

  state.economy.balance += revenue - upkeep;
  state.economy.totalEarned += revenue;
  state.economy.totalSpent += upkeep;

  // Display rates (per second)
  state.economy.revenuePerSec = revenue * TICKS_PER_SEC;
  state.economy.upkeepPerSec = upkeep * TICKS_PER_SEC;
}

// ─── Device usage computation ──────────────────────────────────────────────

function computeDeviceUsage(state: WorldState, cache: RuntimeCache): void {
  // Reset usage for devices that track it
  for (const dev of Object.values(state.devices)) {
    if ('usage' in dev) {
      dev.usage.bandwidth = 0;
      dev.usage.cpu = 0;
      dev.usage.ram = 0;
    }
  }

  // Walk flows and add bandwidth to each device along the path
  for (const flow of Object.values(state.flows)) {
    const path = cache.paths[flow.id];
    if (!path || path.blocked) continue;

    for (const hop of path.hops) {
      const dev = state.devices[hop.deviceId];
      if (!dev) continue;

      switch (dev.kind) {
        case 'server': {
          // Server bandwidth is relative to its NIC capacity
          const nicMbps = dev.specs.nicMbps || 100;
          dev.usage.bandwidth += flow.rateMbps / nicMbps;
          // CPU/RAM based on flow kind
          if (flow.kind === 'http') {
            dev.usage.cpu += (flow.rateMbps / nicMbps) * 0.6;
            dev.usage.ram += (flow.rateMbps / nicMbps) * 0.3;
          }
          break;
        }
        case 'router':
          dev.usage.bandwidth += flow.rateMbps / 1000; // routers handle 1 Gbps
          dev.usage.cpu += flow.rateMbps / 2000;
          break;
        case 'firewall':
          dev.usage.bandwidth += flow.rateMbps / dev.capacityMbps;
          dev.usage.cpu += flow.rateMbps / (dev.capacityMbps * 0.8);
          break;
        case 'ddos_scrubber':
          dev.usage.bandwidth += flow.rateMbps / dev.capacityMbps;
          dev.usage.cpu += flow.rateMbps / (dev.capacityMbps * 0.5);
          break;
      }
    }
  }

  // Clamp usage values
  for (const dev of Object.values(state.devices)) {
    if ('usage' in dev) {
      dev.usage.cpu = Math.min(dev.usage.cpu, 2);       // can go over 1 (overloaded)
      dev.usage.ram = Math.min(dev.usage.ram, 2);
      dev.usage.bandwidth = Math.min(dev.usage.bandwidth, 3);
    }
  }
}

// ─── Health ────────────────────────────────────────────────────────────────

function tickHealth(state: WorldState, cache: RuntimeCache): boolean {
  let changed = false;

  for (const dev of Object.values(state.devices)) {
    const h = dev.health;

    // Repair in progress
    if (h.state === 'repairing' && h.repairEndsAt !== null) {
      if (state.time.tick >= h.repairEndsAt) {
        // Repair complete
        if (h.repairKind === 'full') {
          h.hp = 100;
        } else {
          h.hp = Math.min(100, h.hp + 40);
        }
        h.state = h.hp >= 80 ? 'ok' : 'warning';
        h.fault = null;
        h.faultPort = null;
        h.degradeRatePerTick = 0;
        h.repairEndsAt = null;
        h.repairKind = null;

        // Restore all ports
        for (const p of dev.ports) p.up = true;

        state.stats.devicesRepaired++;
        cache.topologyDirty = true;
        addLog(state, dev.id, 'Repair complete', 'info');
        changed = true;
      }
      continue;
    }

    // Degradation
    if (h.degradeRatePerTick > 0) {
      h.hp = Math.max(0, h.hp - h.degradeRatePerTick);

      if (h.hp <= 0) {
        h.state = 'failed';
        h.degradeRatePerTick = 0;
        // Bring down all ports
        for (const p of dev.ports) p.up = false;
        cache.topologyDirty = true;
        addLog(state, dev.id, `Device failed (${h.fault})`, 'alert');
        changed = true;
      } else if (h.hp < 25) {
        h.state = 'critical';
      } else if (h.hp < 50) {
        h.state = 'warning';
      } else {
        h.state = 'degrading';
      }
    }
  }

  return changed;
}

/**
 * Start a repair on a device. Called from the UI.
 * Preventive repair is cheaper and faster but restores less HP.
 */
export function startRepair(
  state: WorldState,
  deviceId: DeviceId,
  kind: 'preventive' | 'full',
): boolean {
  const dev = state.devices[deviceId];
  if (!dev) return false;
  if (dev.health.state === 'repairing') return false;

  const cost = kind === 'full' ? REPAIR_COST_FULL : REPAIR_COST_PREVENTIVE;
  const duration = kind === 'full' ? REPAIR_DURATION_FULL : REPAIR_DURATION_PREVENTIVE;

  if (state.economy.balance < cost) return false;

  state.economy.balance -= cost;
  state.economy.totalSpent += cost;
  state.economy.repairsCount++;
  if (kind === 'preventive') state.economy.preventiveRepairs++;
  state.stats.preventiveRepairs += kind === 'preventive' ? 1 : 0;

  dev.health.state = 'repairing';
  dev.health.degradeRatePerTick = 0;
  dev.health.repairEndsAt = state.time.tick + duration;
  dev.health.repairKind = kind;

  addLog(state, deviceId, `${kind} repair started`, 'info');
  return true;
}

// ─── Stats ─────────────────────────────────────────────────────────────────

function tickStats(state: WorldState): void {
  const s = state.stats;

  // Compute average service availability this tick
  const services = Object.values(state.services);
  let totalAvail = 0;
  if (services.length > 0) {
    for (const svc of services) {
      totalAvail += svc.availability;
    }
    totalAvail /= services.length;
  } else {
    totalAvail = 1; // no services = nothing is down
  }

  // Accumulate into current bucket
  s.bucketTickCount++;
  s.bucketAvailSum += totalAvail;

  // Roll over to next bucket every 60 seconds (1200 ticks)
  if (s.bucketTickCount >= GAME_MINUTE_TICKS) {
    s.uptimeBuckets[s.currentBucket] = s.bucketAvailSum / s.bucketTickCount;
    s.currentBucket = (s.currentBucket + 1) % 60;
    s.bucketTickCount = 0;
    s.bucketAvailSum = 0;
  }

  // Track downtime
  if (totalAvail < 1) {
    s.totalDowntimeTicks++;
  }
}

// ─── Event scheduling ──────────────────────────────────────────────────────

function scheduleRandomEvent(state: WorldState): void {
  const kinds: EventKind[] = ['hardware_failure', 'ddos', 'port_scan'];
  const kind = kinds[Math.floor(Math.random() * kinds.length)]!;

  // Events spaced 30–90 seconds apart
  const delay = TICKS_PER_SEC * (30 + Math.floor(Math.random() * 60));
  const event: ScheduledEvent = {
    triggerAt: state.time.tick + delay,
    kind,
    payload: {},
  };

  // Insert sorted by triggerAt
  const idx = state.events.findIndex((e) => e.triggerAt > event.triggerAt);
  if (idx < 0) {
    state.events.push(event);
  } else {
    state.events.splice(idx, 0, event);
  }
}

// ─── Carrier particles ────────────────────────────────────────────────────

function tickCarriers(state: WorldState, cache: RuntimeCache): void {
  if (state.speed === 0) return;

  const carriers = cache.carriers;

  // Age existing carriers
  for (let i = carriers.length - 1; i >= 0; i--) {
    const c = carriers[i]!;
    c.age++;

    // Advance along path
    const path = cache.paths[c.flowId];
    if (!path || c.age > CARRIER_MAX_AGE) {
      carriers.splice(i, 1);
      continue;
    }

    // Move forward
    c.progress += 0.04 * state.speed; // speed-adjusted

    if (c.progress >= 1) {
      c.progress = 0;
      c.pathIndex++;

      // Check if we've reached the end of the path
      if (c.pathIndex >= path.hops.length - 1) {
        carriers.splice(i, 1);
        continue;
      }

      // If the next hop is blocked, remove the carrier
      if (path.blocked && path.blockedAt !== null && c.pathIndex >= path.blockedAt) {
        carriers.splice(i, 1);
        continue;
      }
    }
  }

  // Spawn new carriers for active flows
  if (carriers.length < MAX_CARRIERS && state.time.tick % CARRIER_SPAWN_INTERVAL === 0) {
    for (const flow of Object.values(state.flows)) {
      if (carriers.length >= MAX_CARRIERS) break;

      const path = cache.paths[flow.id];
      if (!path || path.hops.length < 2) continue;

      // Spawn rate proportional to flow bandwidth
      const spawnChance = Math.min(1, flow.rateMbps / 10);
      if (Math.random() > spawnChance) continue;

      const carrier: Carrier = {
        flowId: flow.id,
        kind: flow.kind,
        pathIndex: 0,
        progress: 0,
        age: 0,
        size: flow.kind === 'attack' ? 4 : 2.5,
      };
      carriers.push(carrier);
    }
  }
}

// ─── Logging ───────────────────────────────────────────────────────────────

export function addLog(
  state: WorldState,
  deviceId: DeviceId,
  msg: string,
  level: 'info' | 'warn' | 'alert',
): void {
  state.logs.push({ tick: state.time.tick, deviceId, msg, level });
  if (state.logs.length > MAX_LOGS) {
    state.logs.splice(0, state.logs.length - MAX_LOGS);
  }
}

// ─── Topology change notification ──────────────────────────────────────────

/**
 * Mark topology as dirty so paths are re-resolved next tick.
 * Call this whenever devices, cables, or port states change.
 */
export function markTopologyDirty(cache: RuntimeCache): void {
  cache.topologyDirty = true;
  cache.topologyVersion++;
}

// ─── Initial world setup for simulation ────────────────────────────────────

/**
 * Initialize the simulation-related fields on a fresh or loaded world.
 */
export function initSimulation(state: WorldState): void {
  // Ensure all Phase 2 fields exist
  state.flows ??= {};
  state.services ??= {};
  state.events ??= [];
  state.activeIncidents ??= {};
  state.stats ??= {
    uptimeBuckets: new Array(60).fill(1),
    currentBucket: 0,
    bucketTickCount: 0,
    bucketAvailSum: 0,
    ddosBlocked: 0,
    ddosTotal: 0,
    devicesRepaired: 0,
    preventiveRepairs: 0,
    totalDowntimeTicks: 0,
  };
  state.economy ??= {
    balance: 500,
    totalEarned: 0,
    totalSpent: 0,
    revenuePerSec: 0,
    upkeepPerSec: 0,
    repairsCount: 0,
    preventiveRepairs: 0,
  };
  state.unlocks ??= {
    macLearning: false,
    connectedRoutes: false,
    serverM: false,
    serverL: false,
    advancedFwRules: false,
    upstreamFiltering: false,
    carrierUplink: false,
    monitoringAgent: false,
  };
  state.logs ??= [];
  state.time ??= { tick: 0 };
  state.speed ??= 1;

  // Schedule initial events
  if (state.events.length === 0) {
    // First event after 45–90 seconds
    const firstDelay = TICKS_PER_SEC * (45 + Math.floor(Math.random() * 45));
    state.events.push({
      triggerAt: state.time.tick + firstDelay,
      kind: 'hardware_failure',
      payload: {},
    });
    // Second event slightly later
    state.events.push({
      triggerAt: state.time.tick + firstDelay + TICKS_PER_SEC * 30,
      kind: 'port_scan',
      payload: {},
    });
  }
}
