  private unsubs: (() => void)[] = [];
  fit: () => void = () => {};
  private confirming = false;
  private confirmTimer?: ReturnType<typeof setTimeout>;

  // Cached DOM nodes
  private elHint!: HTMLElement;
  private elCounts!: HTMLElement;
  private elZoom!: HTMLElement;
  private elBalance!: HTMLElement;
  private elRevenue!: HTMLElement;
  private elUptime!: HTMLElement;
  private elUtilBar!: HTMLElement;
  private elResetBtn!: HTMLButtonElement;
  private speedBtns: HTMLButtonElement[] = [];

  constructor() {
    super();
    this.shadow = this.attachShadow({ mode: 'open' });
  }

  connectedCallback(): void {
    this.shadow.appendChild(baseStyle());
    const style = document.createElement('style');
    style.textContent = TOPBAR_CSS;
    this.shadow.appendChild(style);

    const root = document.createElement('div');
    root.style.display = 'contents';
    root.innerHTML = `
      <div class="brand">
        <span class="logo">Net<span>Sim</span></span>
        <span class="stage">Phase 2 · Simulation</span>
      </div>
      <div class="hint" aria-live="polite"></div>
      <div class="right">
        <div class="econ">
          <span class="balance" data-el="balance">$0</span>
          <span class="revenue" data-el="revenue">+$0/s</span>
          <span class="uptime" data-el="uptime">—%</span>
          <div class="util-bar"><i data-el="util-bar"></i></div>
        </div>
        <div class="speeds" role="radiogroup" aria-label="Simulation speed"></div>
        <span class="stat counts" data-el="counts"></span>
        <span class="stat" data-el="zoom"></span>
        <button data-action="fit" title="Fit everything in view (F)">Fit</button>
        <button data-action="reset">New</button>
      </div>
    `;
    this.shadow.appendChild(root);

    this.elHint = this.shadow.querySelector('.hint')!;
    this.elCounts = this.shadow.querySelector('[data-el="counts"]')!;
    this.elZoom = this.shadow.querySelector('[data-el="zoom"]')!;
    this.elBalance = this.shadow.querySelector('[data-el="balance"]')!;
    this.elRevenue = this.shadow.querySelector('[data-el="revenue"]')!;
    this.elUptime = this.shadow.querySelector('[data-el="uptime"]')!;
    this.elUtilBar = this.shadow.querySelector('[data-el="util-bar"]')!;
    this.elResetBtn = this.shadow.querySelector('[data-action="reset"]')! as HTMLButtonElement;

    // Speed buttons
    const speedsContainer = this.shadow.querySelector('.speeds')!;
    for (const sp of SPEEDS) {
      const btn = document.createElement('button');
      btn.textContent = sp.label;
      btn.title = sp.title;
      btn.setAttribute('aria-pressed', 'false');
      btn.addEventListener('click', () => {
        world.update((w) => { w.speed = sp.value as 0 | 1 | 2 | 4; });
      });
      speedsContainer.appendChild(btn);
      this.speedBtns.push(btn);
    }

    // Event handlers
    this.shadow.querySelector('[data-action="fit"]')!.addEventListener('click', () => this.fit());
    this.elResetBtn.addEventListener('click', () => this.onReset());

    this.render();
    this.unsubs.push(
      world.subscribe((_s, reason) => { if (reason !== 'camera') this.render(); }),
      ui.subscribe(() => this.render()),
    );
  }

  disconnectedCallback(): void {
    this.unsubs.forEach((u) => u());
  }

  private onReset(): void {
    if (!this.confirming) {
      this.confirming = true;
      this.elResetBtn.textContent = 'Erase layout?';
      this.elResetBtn.className = 'confirm';
      this.confirmTimer = setTimeout(() => {
        this.confirming = false;
        this.elResetBtn.textContent = 'New';
        this.elResetBtn.className = '';
      }, 3500);
      return;
    }
    clearTimeout(this.confirmTimer);
    this.confirming = false;
    resetWorld();
    this.fit();
    this.elResetBtn.textContent = 'New';
    this.elResetBtn.className = '';
  }

  private render(): void {
    const s = world.get();
    const nDev = Object.keys(s.devices).length;
    const nCab = Object.keys(s.cables).length;

    this.elHint.textContent = hintText();
    this.elCounts.textContent = `${nDev} dev · ${nCab} cab`;
    this.elZoom.textContent = `${Math.round(s.camera.scale * 100)}%`;

    // Economy & stats — now proper typed fields
    const economy = s.economy;
    const stats = s.stats;
    const currentSpeed = s.speed;

    this.elBalance.textContent = `$${Math.floor(economy.balance).toLocaleString()}`;
    const rev = economy.revenuePerSec;
    this.elRevenue.textContent = `${rev >= 0 ? '+' : ''}$${rev.toFixed(2)}/s`;
    this.elRevenue.style.color = rev >= 0 ? '' : 'var(--bad)';

    // Compute uptime from rolling buckets
    const buckets = stats.uptimeBuckets;
    const avgUptime = buckets.length ? buckets.reduce((a, b) => a + b, 0) / buckets.length * 100 : 100;
    this.elUptime.textContent = `${avgUptime.toFixed(1)}%`;

    // Uplink utilization — computed from runtime cable load or flow data
    const uplink = Object.values(s.devices).find((d) => d.kind === 'uplink');
    if (uplink && uplink.kind === 'uplink') {
      // Sum bandwidth of all flows entering the uplink
      const totalMbps = Object.values(s.flows).reduce((sum, f) => sum + f.rateMbps, 0);
      const pct = Math.min(100, (totalMbps / uplink.bandwidthMbps) * 100);
      this.elUtilBar.style.width = `${pct}%`;
    }

    // Speed buttons
    for (let i = 0; i < SPEEDS.length; i++) {
      this.speedBtns[i]!.setAttribute('aria-pressed', String(SPEEDS[i]!.value === currentSpeed));
    }
  }
}
