      padding-left: env(safe-area-inset-left, 0px); padding-right: env(safe-area-inset-right, 0px);
    }
    footer { padding-bottom: 10px; }
  }
`;

// ---------- DOM helpers ----------

function el(tag: string, cls?: string, text?: string): HTMLElement {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text !== undefined) e.textContent = text;
  return e;
}

function makeInput(id: string, value: string, opts: {
  placeholder?: string;
  readonly?: boolean;
  ariaLabel?: string;
  check?: Check;
  onCommit?: (v: string) => void;
}): HTMLInputElement {
  const inp = document.createElement('input');
  inp.id = id;
  inp.value = value;
  inp.spellcheck = false;
  inp.autocomplete = 'off';
  if (opts.placeholder) inp.placeholder = opts.placeholder;
  if (opts.readonly) inp.readOnly = true;
  if (opts.ariaLabel) inp.setAttribute('aria-label', opts.ariaLabel);
  if (opts.check && opts.check.level !== 'hint') inp.className = opts.check.level;
  inp.addEventListener('keydown', (e) => { if (e.key === 'Enter') inp.blur(); });
  if (opts.onCommit) {
    inp.addEventListener('change', () => opts.onCommit!(inp.value.trim()));
  }
  return inp;
}

function makeField(label: string, value: string, opts: {
  id: string;
  placeholder?: string;
  readonly?: boolean;
  check?: Check;
  onCommit?: (v: string) => void;
}): HTMLElement {
  const wrap = document.createElement('label');
  wrap.className = 'field';
  const span = el('span', undefined, label);
  const inp = makeInput(opts.id, value, opts);
  wrap.appendChild(span);
  wrap.appendChild(inp);
  if (opts.check) {
    const msg = el('span', `msg ${opts.check.level}`, opts.check.msg);
    wrap.appendChild(msg);
  }
  return wrap;
}

function makeMsgs(checks: (Check | null)[]): HTMLElement | null {
  const shown = checks.filter((c): c is NonNullable<Check> => !!c && c.level !== 'hint');
  if (!shown.length) return null;
  const div = el('div', 'msgs');
  for (const c of shown) div.appendChild(el('span', c.level, c.msg));
  return div;
}

function makeSelect(id: string, options: { value: string; label: string }[], selected: string, ariaLabel: string, onChange: (v: string) => void): HTMLSelectElement {
  const sel = document.createElement('select');
  sel.id = id;
  sel.setAttribute('aria-label', ariaLabel);
  for (const o of options) {
    const opt = document.createElement('option');
    opt.value = o.value;
    opt.textContent = o.label;
    opt.selected = o.value === selected;
    sel.appendChild(opt);
  }
  sel.addEventListener('change', () => onChange(sel.value));
  return sel;
}

// ---------- Inspector ----------

export class NsInspector extends HTMLElement {
  private shadow: ShadowRoot;
  private unsubs: (() => void)[] = [];

  constructor() {
    super();
    this.shadow = this.attachShadow({ mode: 'open' });
  }

  connectedCallback(): void {
    this.shadow.appendChild(baseStyle());
    const style = document.createElement('style');
    style.textContent = INSPECTOR_CSS;
    this.shadow.appendChild(style);

    this.render();
    this.unsubs.push(
      world.subscribe((_s, reason) => { if (reason !== 'camera') this.render(); }),
      ui.subscribe(() => this.render()),
    );
  }

  disconnectedCallback(): void {
    this.unsubs.forEach((u) => u());
  }

  // ---------- per-kind body builders ----------

  private uplinkBody(d: Extract<Device, { kind: 'uplink' }>): HTMLElement {
    const wrap = el('div');
    const section = el('section');
    section.appendChild(el('h3', undefined, 'Internet connection'));

    const c = parseCidr(d.publicSubnet)!;
    const size = 2 ** (32 - c.prefix);

    const kv = el('dl', 'kv');
    kv.innerHTML = `
      <dt>Public block</dt><dd>${d.publicSubnet}</dd>
      <dt>Usable IPs</dt><dd>${formatIp(c.net + 1)} – ${formatIp(c.net + size - 2)} (${size - 2})</dd>
      <dt>Bandwidth</dt><dd>${d.bandwidthMbps} Mbps · ${d.uplinkTier} tier</dd>
      <dt>Uplink IP</dt><dd>${d.uplinkIp}</dd>
    `;
    section.appendChild(kv);

    section.appendChild(el('p', 'note',
      'All visitors and attacks arrive through this port. Give your edge router or servers addresses from the public block.'));

    wrap.appendChild(section);
    return wrap;
  }

  private serverBody(s: WorldState, d: Extract<Device, { kind: 'server' }>): HTMLElement {
    const wrap = el('div');
    const net = subnetOf(d.ip, d.mask);
    const edit = (fn: (x: Extract<Device, { kind: 'server' }>) => void) => editDevice(d.id, 'server', fn);

    // Network section
    const netSec = el('section');
    netSec.appendChild(el('h3', undefined, 'Network'));
    netSec.appendChild(makeField('IP address', d.ip, {
      id: 'srv-ip', placeholder: '192.168.1.10',
      check: checkIp(d.ip) ?? duplicateCheck(s, d.ip, d.name),
      onCommit: (v) => edit((x) => { x.ip = v; }),
    }));
    netSec.appendChild(makeField('Subnet mask', d.mask, {
      id: 'srv-mask', placeholder: '255.255.255.0',
      check: checkMask(d.mask),
      onCommit: (v) => edit((x) => { x.mask = v; }),
    }));
    netSec.appendChild(makeField('Gateway', d.gateway, {
      id: 'srv-gw', placeholder: '192.168.1.1',
      check: serverGatewayCheck(d),
      onCommit: (v) => edit((x) => { x.gateway = v; }),
    }));

    const kv = el('dl', 'kv');
    kv.innerHTML = `<dt>Subnet</dt><dd>${net ? formatCidr(net) : '—'}</dd><dt>MAC</dt><dd>${d.mac}</dd>`;
    netSec.appendChild(kv);
    wrap.appendChild(netSec);

    // Hardware section
    const hwSec = el('section');
    const h3 = el('h3');
    h3.innerHTML = `Hardware <span class="mono">Tier ${d.tier}</span>`;
    hwSec.appendChild(h3);
    const hwKv = el('dl', 'kv');
    hwKv.innerHTML = `
      <dt>CPU</dt><dd>${d.specs.cpuCores} cores</dd>
      <dt>Memory</dt><dd>${d.specs.ramGB} GB</dd>
      <dt>Storage</dt><dd>${d.specs.storageGB} GB</dd>
      <dt>NIC</dt><dd>${d.specs.nicMbps >= 1000 ? `${d.specs.nicMbps / 1000} Gbps` : `${d.specs.nicMbps} Mbps`}</dd>
    `;
    hwSec.appendChild(hwKv);
    wrap.appendChild(hwSec);

    // Roles section
    const rolesSec = el('section');
    rolesSec.appendChild(el('h3', undefined, 'Roles'));
    const roles = d.roles;
    if (roles.length === 0) {
      rolesSec.appendChild(el('p', 'note', 'No roles installed. Deploy a static web service to start earning revenue.'));
    } else {
      const roleList = el('div', 'derived');
      for (const r of roles) {
        roleList.appendChild(el('span', undefined, `${r.role} (port ${r.port}) — active`));
      }
      rolesSec.appendChild(roleList);
    }
    wrap.appendChild(rolesSec);

    return wrap;
  }

  private routerBody(s: WorldState, d: Extract<Device, { kind: 'router' }>): HTMLElement {
    const wrap = el('div');
    const edit = (fn: (x: Extract<Device, { kind: 'router' }>) => void) => editDevice(d.id, 'router', fn);
    const connected = routerSubnets(d);

    // Interfaces
    const ifSec = el('section');
    ifSec.appendChild(el('h3', undefined, 'Interfaces'));
    for (const itf of d.interfaces) {
      const label = d.ports[itf.port]!.label;
      const ipCheck = checkIp(itf.ip, '') ?? duplicateCheck(s, itf.ip, `${d.name} ${label}`);
      const maskCheck = itf.ip ? checkMask(itf.mask) : null;

      const row = el('div', 'row if-row');
      const portLabel = el('span', 'pl');
      portLabel.innerHTML = `${label}<br /><span class="side">${SIDE_NAME[portSide(d, itf.port)]}</span>`;
      row.appendChild(portLabel);
      row.appendChild(makeInput(`rt-${itf.port}-ip`, itf.ip, {
        placeholder: 'unassigned', ariaLabel: `${label} IP`, check: ipCheck,
        onCommit: (v) => edit((x) => { x.interfaces[itf.port]!.ip = v; }),
      }));
      row.appendChild(makeInput(`rt-${itf.port}-mask`, itf.mask, {
        placeholder: '/24', ariaLabel: `${label} mask`, check: maskCheck,
        onCommit: (v) => edit((x) => { x.interfaces[itf.port]!.mask = v; }),
      }));
      ifSec.appendChild(row);

      const msgs = makeMsgs([ipCheck, maskCheck, overlapCheck(d, itf.port)]);
      if (msgs) ifSec.appendChild(msgs);
    }
    wrap.appendChild(ifSec);

    // Connected networks
    const conSec = el('section');
    conSec.appendChild(el('h3', undefined, 'Connected networks'));
    if (connected.length) {
      const derived = el('div', 'derived');
      for (const n of connected) derived.appendChild(el('span', undefined, `${formatCidr(n.cidr)} → ${d.ports[n.port]!.label}`));
      conSec.appendChild(derived);
    } else {
      conSec.appendChild(el('p', 'note', 'Give an interface an IP to connect its subnet.'));
    }
    wrap.appendChild(conSec);

    // Static routes
    const rtSec = el('section');
    rtSec.appendChild(el('h3', undefined, 'Static routes'));
    if (d.routes.length === 0) {
      rtSec.appendChild(el('p', 'note', "No static routes. A default route (0.0.0.0/0) usually points at your uplink side."));
    }
    for (let i = 0; i < d.routes.length; i++) {
      const rt = d.routes[i]!;
      const destCheck = checkCidr(rt.dest, false);
      const hopCheck = nextHopCheck(d, rt.nextHop, rt.iface);
      const upd = (fn: (r: typeof rt) => void) => edit((x) => { const r = x.routes[i]; if (r) fn(r); });

      const card = el('div', 'card');

      const row1 = el('div', 'row rt-row1');
      row1.appendChild(makeInput(`${rt.id}-dest`, rt.dest, {
        placeholder: 'destination, e.g. 0.0.0.0/0', ariaLabel: 'Destination', check: destCheck,
        onCommit: (v) => upd((r) => { r.dest = v; }),
      }));
      row1.appendChild(makeInput(`${rt.id}-hop`, rt.nextHop, {
        placeholder: 'next hop IP', ariaLabel: 'Next hop', check: hopCheck,
        onCommit: (v) => upd((r) => { r.nextHop = v; }),
      }));
      card.appendChild(row1);

      const row2 = el('div', 'row rt-row2');
      row2.appendChild(makeSelect(
        `${rt.id}-if`,
        d.ports.map((p) => ({ value: String(p.index), label: `out ${p.label}` })),
        String(rt.iface), 'Interface',
        (v) => upd((r) => { r.iface = Number(v); }),
      ));
      row2.appendChild(makeInput(`${rt.id}-metric`, String(rt.metric), {
        placeholder: 'metric', ariaLabel: 'Metric',
        onCommit: (v) => upd((r) => { const n = Number(v); r.metric = Number.isFinite(n) && n >= 0 ? Math.round(n) : r.metric; }),
      }));
      const delBtn = document.createElement('button');
      delBtn.className = 'icon-btn danger';
      delBtn.title = 'Delete route';
      delBtn.setAttribute('aria-label', 'Delete route');
      delBtn.textContent = '✕';
      delBtn.addEventListener('click', () => edit((x) => { x.routes.splice(i, 1); }));
      row2.appendChild(delBtn);
      card.appendChild(row2);

      const msgs = makeMsgs([destCheck, hopCheck]);
      if (msgs) card.appendChild(msgs);
      rtSec.appendChild(card);
    }

    const addBtn = document.createElement('button');
    addBtn.className = 'add';
    addBtn.textContent = '+ Add route';
    addBtn.addEventListener('click', () => edit((x) => {
      const firstUp = x.interfaces.find((it) => it.ip)?.port ?? 0;
      x.routes.push({ id: genId('rt'), dest: '0.0.0.0/0', nextHop: '', iface: firstUp, metric: 1 });
    }));
    rtSec.appendChild(addBtn);
    wrap.appendChild(rtSec);

    return wrap;
  }

  private switchBody(d: Extract<Device, { kind: 'switch' }>): HTMLElement {
    const wrap = el('div');
    const sec = el('section');
    sec.appendChild(el('h3', undefined, 'MAC table'));
    const n = Object.keys(d.macTable).length;
    sec.appendChild(el('p', 'note', n ? `${n} entries` : 'Empty. The switch learns addresses once traffic flows through it.'));
    sec.appendChild(el('p', 'note', 'Everything plugged into one switch shares a subnet. Use a router to join different subnets.'));
    wrap.appendChild(sec);
    return wrap;
  }

  private firewallBody(d: Extract<Device, { kind: 'firewall' }>): HTMLElement {
    const wrap = el('div');
    const edit = (fn: (x: Extract<Device, { kind: 'firewall' }>) => void) => editDevice(d.id, 'firewall', fn);

    // Interfaces section (multi-port zone-based, Cisco ASA style)
    const ifSec = el('section');
    ifSec.appendChild(el('h3', undefined, 'Interfaces'));
    ifSec.appendChild(el('p', 'note', 'Higher security level → lower = allowed by default. Lower → higher = denied unless a rule allows.'));

    for (const iface of d.interfaces) {
      const card = el('div', 'card');
      const row = el('div', 'row fw-if-row');

      const nameEl = el('span', 'pl', iface.name);
      row.appendChild(nameEl);

      const lvlInput = makeInput(`fw-if-${iface.port}-lvl`, String(iface.securityLevel), {
        placeholder: '0-100', ariaLabel: `${iface.name} security level`,
        onCommit: (v) => {
          const n = Number(v);
          if (Number.isFinite(n) && n >= 0 && n <= 100) {
            edit((x) => {
              const f = x.interfaces.find((i) => i.port === iface.port);
              if (f) f.securityLevel = Math.round(n);
            });
          }
        },
      });
      row.appendChild(lvlInput);

      row.appendChild(makeInput(`fw-if-${iface.port}-ip`, iface.ip, {
        placeholder: 'unassigned', ariaLabel: `${iface.name} IP`,
        onCommit: (v) => edit((x) => {
          const f = x.interfaces.find((i) => i.port === iface.port);
          if (f) f.ip = v;
        }),
      }));

      row.appendChild(makeInput(`fw-if-${iface.port}-mask`, iface.mask, {
        placeholder: '/24', ariaLabel: `${iface.name} mask`,
        onCommit: (v) => edit((x) => {
          const f = x.interfaces.find((i) => i.port === iface.port);
          if (f) f.mask = v;
        }),
      }));

      card.appendChild(row);

      const sideLabel = el('span', 'sub', `port ${iface.port} · security ${iface.securityLevel}`);
      card.appendChild(sideLabel);
      ifSec.appendChild(card);
    }
    wrap.appendChild(ifSec);

    // Rules section
    const rulesSec = el('section');
    const h3 = el('h3');
    h3.innerHTML = `Rules <span class="mono">${d.rules.length}</span>`;
    rulesSec.appendChild(h3);
    rulesSec.appendChild(el('p', 'note', 'Checked top to bottom. The first match decides.'));

    const move = (i: number, dir: -1 | 1) => edit((x) => {
      const j = i + dir;
      if (j < 0 || j >= x.rules.length) return;
      [x.rules[i], x.rules[j]] = [x.rules[j]!, x.rules[i]!];
    });

    for (let i = 0; i < d.rules.length; i++) {
      const r = d.rules[i]!;
      const upd = (fn: (x: typeof r) => void) => edit((x) => { const rr = x.rules[i]; if (rr) fn(rr); });
      const srcC = checkCidr(r.src, true);
      const dstC = checkCidr(r.dst, true);
      const portC = r.protocol === 'icmp' ? null : checkPorts(r.ports);

      const card = el('div', 'card');

      // Row 1: # action protocol ... move/delete
      const row1 = el('div', 'row fw-row1');
      row1.appendChild(el('span', 'num', `#${i + 1}`));

      const actSel = makeSelect(`${r.id}-act`,
        [{ value: 'allow', label: 'allow' }, { value: 'deny', label: 'deny' }],
        r.action, 'Action',
        (v) => upd((x) => { x.action = v as FwAction; }),
      );
      actSel.style.color = r.action === 'deny' ? 'var(--bad)' : 'var(--ok)';
      row1.appendChild(actSel);

      row1.appendChild(makeSelect(`${r.id}-proto`,
        ['any', 'tcp', 'udp', 'icmp'].map((p) => ({ value: p, label: p })),
        r.protocol, 'Protocol',
        (v) => upd((x) => { x.protocol = v as FwProtocol; }),
      ));

      row1.appendChild(el('span')); // spacer

      const upBtn = document.createElement('button');
      upBtn.className = 'icon-btn';
      upBtn.title = 'Move up';
      upBtn.setAttribute('aria-label', 'Move rule up');
      upBtn.textContent = '↑';
      upBtn.disabled = i === 0;
      upBtn.addEventListener('click', () => move(i, -1));
      row1.appendChild(upBtn);

      const downBtn = document.createElement('button');
      downBtn.className = 'icon-btn';
      downBtn.title = 'Move down';
      downBtn.setAttribute('aria-label', 'Move rule down');
      downBtn.textContent = '↓';
      downBtn.disabled = i === d.rules.length - 1;
      downBtn.addEventListener('click', () => move(i, 1));
      row1.appendChild(downBtn);

      const delRuleBtn = document.createElement('button');
      delRuleBtn.className = 'icon-btn danger';
      delRuleBtn.title = 'Delete rule';
      delRuleBtn.setAttribute('aria-label', 'Delete rule');
      delRuleBtn.textContent = '✕';
      delRuleBtn.addEventListener('click', () => edit((x) => { x.rules.splice(i, 1); }));
      row1.appendChild(delRuleBtn);

      card.appendChild(row1);

      // Row 2: src, dst, ports
      const row2 = el('div', 'row fw-row2');
      row2.appendChild(el('span', 'lbl', 'source'));
      row2.appendChild(el('span', 'lbl', 'destination'));
      row2.appendChild(el('span', 'lbl', 'ports'));

      row2.appendChild(makeInput(`${r.id}-src`, r.src, {
        placeholder: 'any', ariaLabel: 'Source', check: srcC,
        onCommit: (v) => upd((x) => { x.src = v || 'any'; }),
      }));
      row2.appendChild(makeInput(`${r.id}-dst`, r.dst, {
        placeholder: 'any', ariaLabel: 'Destination', check: dstC,
        onCommit: (v) => upd((x) => { x.dst = v || 'any'; }),
      }));
      row2.appendChild(makeInput(`${r.id}-ports`, r.protocol === 'icmp' ? '—' : r.ports, {
        placeholder: 'any', ariaLabel: 'Ports', check: portC,
        onCommit: (v) => upd((x) => { x.ports = v || 'any'; }),
      }));
      card.appendChild(row2);

      // Log checkbox
      const logLabel = document.createElement('label');
      logLabel.className = 'check';
      const logCb = document.createElement('input');
      logCb.type = 'checkbox';
      logCb.checked = r.log;
      logCb.addEventListener('change', () => upd((x) => { x.log = logCb.checked; }));
      logLabel.appendChild(logCb);
      logLabel.appendChild(document.createTextNode(' Log matches'));
      card.appendChild(logLabel);

      const msgs = makeMsgs([srcC, dstC, portC]);
      if (msgs) card.appendChild(msgs);
      rulesSec.appendChild(card);
    }

    const addRuleBtn = document.createElement('button');
    addRuleBtn.className = 'add';
    addRuleBtn.textContent = '+ Add rule';
    addRuleBtn.addEventListener('click', () => edit((x) => {
      x.rules.push({ id: genId('fw'), action: 'deny', protocol: 'any', srcZone: 'any', dstZone: 'any', src: 'any', dst: 'any', ports: 'any', log: true });
    }));
    rulesSec.appendChild(addRuleBtn);
    wrap.appendChild(rulesSec);

    // Default policy
    const polSec = el('section');
    polSec.appendChild(el('h3', undefined, 'When no rule matches'));
    const seg = el('div', 'seg');
    seg.setAttribute('role', 'radiogroup');
    seg.setAttribute('aria-label', 'Default policy');
    for (const p of ['allow', 'deny'] as const) {
      const btn = document.createElement('button');
      btn.setAttribute('aria-pressed', String(d.defaultPolicy === p));
      btn.textContent = `${p} traffic`;
      btn.addEventListener('click', () => edit((x) => { x.defaultPolicy = p; }));
      seg.appendChild(btn);
    }
    polSec.appendChild(seg);
    const capKv = el('dl', 'kv');
    capKv.innerHTML = `<dt>Capacity</dt><dd>${d.capacityMbps / 1000} Gbps</dd>`;
    polSec.appendChild(capKv);
    wrap.appendChild(polSec);

    return wrap;
  }

  private ddosScrubberBody(d: Extract<Device, { kind: 'ddos_scrubber' }>): HTMLElement {
    const wrap = el('div');
    const edit = (fn: (x: Extract<Device, { kind: 'ddos_scrubber' }>) => void) => editDevice(d.id, 'ddos_scrubber', fn);

    // Overview section
    const overSec = el('section');
    overSec.appendChild(el('h3', undefined, 'DDoS Scrubber'));
    const kv = el('dl', 'kv');
    kv.innerHTML = `
      <dt>Capacity</dt><dd>${d.capacityMbps / 1000} Gbps</dd>
      <dt>SYN protection</dt><dd>${d.synProtection ? 'Enabled' : 'Disabled'}</dd>
    `;
    overSec.appendChild(kv);

    // SYN protection toggle
    const synLabel = document.createElement('label');
    synLabel.className = 'check';
    const synCb = document.createElement('input');
    synCb.type = 'checkbox';
    synCb.checked = d.synProtection;
    synCb.addEventListener('change', () => edit((x) => { x.synProtection = synCb.checked; }));
    synLabel.appendChild(synCb);
    synLabel.appendChild(document.createTextNode(' SYN flood protection'));
    overSec.appendChild(synLabel);
    wrap.appendChild(overSec);

    // Rate limits
    const rlSec = el('section');
    const h3 = el('h3');
    h3.innerHTML = `Rate limits <span class="mono">${d.rateLimits.length}</span>`;
    rlSec.appendChild(h3);

    for (let i = 0; i < d.rateLimits.length; i++) {
      const rl = d.rateLimits[i]!;
      const upd = (fn: (x: typeof rl) => void) => edit((x) => { const r = x.rateLimits[i]; if (r) fn(r); });

      const card = el('div', 'card');
      const row = el('div', 'row rt-row1');
      row.appendChild(makeInput(`rl-${rl.id}-src`, rl.src, {
        placeholder: 'source CIDR or any', ariaLabel: 'Source CIDR',
        onCommit: (v) => upd((x) => { x.src = v || 'any'; }),
      }));
      row.appendChild(makeInput(`rl-${rl.id}-max`, String(rl.maxMbps), {
        placeholder: 'max Mbps', ariaLabel: 'Max bandwidth',
        onCommit: (v) => { const n = Number(v); if (Number.isFinite(n) && n > 0) upd((x) => { x.maxMbps = n; }); },
      }));
      card.appendChild(row);

      const row2 = el('div', 'row rt-row2');
      row2.appendChild(makeSelect(`rl-${rl.id}-act`,
        [{ value: 'limit', label: 'Rate limit' }, { value: 'drop', label: 'Drop all' }],
        rl.action, 'Action',
        (v) => upd((x) => { x.action = v as 'limit' | 'drop'; }),
      ));

      const enLabel = document.createElement('label');
      enLabel.className = 'check';
      const enCb = document.createElement('input');
      enCb.type = 'checkbox';
      enCb.checked = rl.enabled;
      enCb.addEventListener('change', () => upd((x) => { x.enabled = enCb.checked; }));
      enLabel.appendChild(enCb);
      enLabel.appendChild(document.createTextNode(' On'));
      row2.appendChild(enLabel);

      const delBtn = document.createElement('button');
      delBtn.className = 'icon-btn danger';
      delBtn.title = 'Delete rule';
      delBtn.textContent = '✕';
      delBtn.addEventListener('click', () => edit((x) => { x.rateLimits.splice(i, 1); }));
      row2.appendChild(delBtn);
      card.appendChild(row2);

      rlSec.appendChild(card);
    }

    const addBtn = document.createElement('button');
    addBtn.className = 'add';
    addBtn.textContent = '+ Add rate limit';
    addBtn.addEventListener('click', () => edit((x) => {
      x.rateLimits.push({ id: genId('fw'), src: 'any', maxMbps: 100, action: 'limit', enabled: true });
    }));
    rlSec.appendChild(addBtn);
    wrap.appendChild(rlSec);

    return wrap;
  }

  // ---------- shared sections ----------

  private portsSection(s: WorldState, d: Device): HTMLElement {
    const sec = el('section');
    sec.appendChild(el('h3', undefined, 'Ports'));
    const used = portUsage(s);
    const list = el('ul', 'ports');

    for (const p of d.ports) {
      const li = document.createElement('li');
      const pl = el('span', 'pl', p.label);
      li.appendChild(pl);

      const cid = used.get(`${d.id}:${p.index}`);
      const cable = cid ? s.cables[cid] : undefined;
      if (cable) {
        const other = cable.a.deviceId === d.id && cable.a.port === p.index ? cable.b : cable.a;
        const od = s.devices[other.deviceId];
        li.appendChild(el('span', 'linked', `→ ${od?.name ?? '?'} ${od?.ports[other.port]?.label ?? ''}`));
      } else {
        li.appendChild(el('span', 'free', 'free'));
      }
      li.appendChild(el('span', 'side', SIDE_NAME[portSide(d, p.index)]));
      list.appendChild(li);
    }
    sec.appendChild(list);
    return sec;
  }

  private healthSection(d: Device): HTMLElement {
    const sec = el('section');
    const h3 = el('h3');
    const stateLabel = d.health.state === 'ok' ? 'OK' : d.health.state;
    const stateColor = d.health.state === 'ok' ? 'var(--ok)'
      : (d.health.state === 'degrading' || d.health.state === 'warning') ? 'var(--warn)'
      : 'var(--bad)';
    h3.innerHTML = `Health <span class="mono" style="color:${stateColor}">${Math.round(d.health.hp)}% · ${stateLabel}</span>`;
    sec.appendChild(h3);

    const bar = el('div', 'bar');
    const barInner = el('i');
    barInner.style.width = `${d.health.hp}%`;
    if (d.health.hp < 50) barInner.style.background = 'var(--warn)';
    if (d.health.hp < 20) barInner.style.background = 'var(--bad)';
    bar.appendChild(barInner);
    sec.appendChild(bar);

    return sec;
  }

  // ---------- device body dispatch ----------

  private deviceBody(s: WorldState, d: Device): HTMLElement {
    switch (d.kind) {
      case 'uplink': return this.uplinkBody(d);
      case 'server': return this.serverBody(s, d);
      case 'router': return this.routerBody(s, d);
      case 'switch': return this.switchBody(d);
      case 'firewall': return this.firewallBody(d);
      case 'ddos_scrubber': return this.ddosScrubberBody(d);
      default: return assertNever(d);
    }
  }

  // ---------- full renders ----------

  private renderDevice(s: WorldState, d: Device): DocumentFragment {
    const frag = document.createDocumentFragment();
    const def = DEVICE_DEFS[d.kind];

    // Header
    const header = document.createElement('header');
    header.style.setProperty('--kind', KIND_CSS[d.kind]);

    const glyphSpan = el('span', 'glyph');
    glyphSpan.innerHTML = kindGlyph(d.kind, 30);
    header.appendChild(glyphSpan);

    const titles = el('div', undefined);
    titles.className = 'titles';
    titles.appendChild(el('span', 'eyebrow', `${def.label} · ${d.id}`));

    const nameInput = document.createElement('input');
    nameInput.id = 'dev-name';
    nameInput.setAttribute('aria-label', 'Device name');
    nameInput.value = d.name;
    nameInput.spellcheck = false;
    nameInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') nameInput.blur(); });
    nameInput.addEventListener('change', () => {
      const v = nameInput.value.trim();
      if (v) world.update((w) => { const x = w.devices[d.id]; if (x) x.name = v.slice(0, 24); });
      else nameInput.value = d.name; // revert
    });
    titles.appendChild(nameInput);
    header.appendChild(titles);

    const closeBtn = document.createElement('button');
    closeBtn.className = 'close ghost';
    closeBtn.setAttribute('aria-label', 'Close panel');
    closeBtn.textContent = '×';
    closeBtn.addEventListener('click', () => select(null));
    header.appendChild(closeBtn);

    frag.appendChild(header);

    // Body
    const body = el('div', 'body');
    body.appendChild(this.deviceBody(s, d));
    body.appendChild(this.portsSection(s, d));
    body.appendChild(this.healthSection(d));
    frag.appendChild(body);

    // Footer
    const footer = document.createElement('footer');
    const rotateBtn = document.createElement('button');
    rotateBtn.textContent = 'Rotate ports';
    rotateBtn.title = 'Turn the ports 90° clockwise (R)';
    rotateBtn.addEventListener('click', () => rotateDevice(d.id));
    footer.appendChild(rotateBtn);
    footer.appendChild(el('span', 'grow'));

    if (d.kind !== 'uplink') {
      const delBtn = document.createElement('button');
      delBtn.className = 'danger';
      delBtn.textContent = `Delete ${def.label.toLowerCase()}`;
      delBtn.addEventListener('click', () => deleteDevice(d.id));
      footer.appendChild(delBtn);
    }
    frag.appendChild(footer);

    return frag;
  }

  private renderCable(s: WorldState, c: Cable): DocumentFragment {
    const frag = document.createDocumentFragment();

    const endLabel = (e: Cable['a']) => {
      const d = s.devices[e.deviceId];
      return `${d?.name ?? '?'} · ${d?.ports[e.port]?.label ?? '?'}`;
    };

    let len = 0;
    for (let i = 0; i < c.path.length - 1; i++) {
      len += Math.hypot(c.path[i + 1]!.x - c.path[i]!.x, c.path[i + 1]!.y - c.path[i]!.y);
    }

    // Header
    const header = document.createElement('header');
    const glyphSpan = el('span', undefined);
    glyphSpan.style.color = 'var(--ink-dim)';
    glyphSpan.innerHTML = cableGlyph(30);
    header.appendChild(glyphSpan);

    const titles = el('div', 'titles');
    titles.appendChild(el('span', 'eyebrow', `Cable · ${c.id}`));
    const strong = document.createElement('strong');
    strong.textContent = `${endLabel(c.a)} ↔ ${endLabel(c.b)}`;
    titles.appendChild(strong);
    header.appendChild(titles);

    const closeBtn = document.createElement('button');
    closeBtn.className = 'close ghost';
    closeBtn.setAttribute('aria-label', 'Close panel');
    closeBtn.textContent = '×';
    closeBtn.addEventListener('click', () => select(null));
    header.appendChild(closeBtn);
    frag.appendChild(header);

    // Body
    const body = el('div', 'body');
    const sec = el('section');
    sec.appendChild(el('h3', undefined, 'Type'));

    const seg = el('div', 'seg');
    seg.setAttribute('role', 'radiogroup');
    seg.setAttribute('aria-label', 'Cable type');
    const types: CableType[] = ['ethernet', 'fibre', 'crossover'];
    for (const t of types) {
      const btn = document.createElement('button');
      btn.setAttribute('aria-pressed', String(c.type === t));
      btn.textContent = t;
      btn.addEventListener('click', () => setCableType(c.id, t));
      seg.appendChild(btn);
    }
    sec.appendChild(seg);

    const kv = el('dl', 'kv');
    kv.innerHTML = `
      <dt>Bandwidth</dt><dd>${CABLE_BANDWIDTH[c.type] / 1000} Gbps</dd>
      <dt>Length</dt><dd>${(len / CELL).toFixed(1)} cells</dd>
    `;
    sec.appendChild(kv);
    body.appendChild(sec);
    frag.appendChild(body);

    // Footer
    const footer = document.createElement('footer');
    footer.appendChild(el('span', 'grow'));
    const delBtn = document.createElement('button');
    delBtn.className = 'danger';
    delBtn.textContent = 'Delete cable';
    delBtn.addEventListener('click', () => deleteCable(c.id));
    footer.appendChild(delBtn);
    frag.appendChild(footer);

    return frag;
  }

  // ---------- main render ----------

  private render(): void {
    const s = world.get();
    const sel = ui.get().selection;
    const d = sel?.type === 'device' ? s.devices[sel.id] : undefined;
    const c = sel?.type === 'cable' ? s.cables[sel.id] : undefined;

    this.hidden = !d && !c;
    if (this.hidden) return;

    // Clear content (keep styles)
    const styles = this.shadow.querySelectorAll('style');
    while (this.shadow.childNodes.length > styles.length) {
      this.shadow.removeChild(this.shadow.lastChild!);
    }

    if (d) this.shadow.appendChild(this.renderDevice(s, d));
    else if (c) this.shadow.appendChild(this.renderCable(s, c));
  }
}
customElements.define('ns-inspector', NsInspector);
// Tool palette — plain DOM custom element (no Lit).
import { CABLE_BANDWIDTH, CABLE_PRICE } from '../balance';
import { DEVICE_DEFS, PLACEABLE_KINDS } from '../state/devices';
import type { CableType } from '../state/types';
import { setTool, ui } from '../state/world';
import { cableGlyph, kindGlyph, selectGlyph } from './glyphs';
import { baseStyle } from './styles';

const CABLE_TYPES: { type: CableType; label: string; color: string }[] = [
  { type: 'ethernet', label: 'Ethernet', color: '#b4c2d4' },
  { type: 'fibre', label: 'Fibre', color: '#ffa94d' },
  { type: 'crossover', label: 'Crossover', color: '#5fb8ff' },
];

const PALETTE_CSS = `
  :host {
    display: flex; flex-direction: column; gap: 6px;
    background: var(--paper); border-right: 1px solid var(--line);
    padding: 10px 8px; overflow-y: auto;
  }
  .group { display: flex; flex-direction: column; gap: 6px; }
  .sep { height: 1px; background: var(--line); margin: 4px 2px; flex: none; }
  .tool {
    display: grid; justify-items: center; gap: 2px; padding: 7px 4px 6px; width: 76px;
    background: transparent; border: 1px solid transparent; border-radius: 8px; color: var(--ink-dim);
  }
  .tool:hover { background: var(--raised); border-color: var(--line); color: var(--ink); }
  .tool[aria-pressed="true"] {
    background: var(--raised); border-color: var(--accent); color: var(--ink);
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 30%, transparent);
  }
  .name { font-size: 11.5px; font-weight: 500; }
  .price { font-family: var(--font-mono); font-size: 10px; color: var(--ink-faint); }
  .cables { display: flex; flex-direction: column; gap: 4px; }
  .chip {
    display: flex; align-items: center; gap: 6px; min-height: 28px; padding: 3px 7px;
    font-size: 11px; border-radius: 6px; background: transparent; border-color: var(--line);
  }
  .chip[aria-pressed="true"] { border-color: var(--accent); background: var(--raised); }
  .swatch { width: 14px; height: 3px; border-radius: 2px; flex: none; }
  .glyph { display: flex; align-items: center; justify-content: center; }
  @media (max-width: 759px) {
    :host {
      flex-direction: row; border-right: 0; border-top: 1px solid var(--line);
      padding: 6px max(8px, env(safe-area-inset-right, 0px)) calc(6px + env(safe-area-inset-bottom, 0px)) max(8px, env(safe-area-inset-left, 0px));
      overflow-x: auto; overflow-y: hidden; gap: 4px; align-items: stretch;
    }
    .group { flex-direction: row; gap: 4px; }
    .sep { width: 1px; height: auto; margin: 4px 2px; }
    .tool { width: 64px; flex: none; }
    .cables { flex-direction: column; justify-content: center; }
    .chip { min-height: 22px; padding: 1px 6px; font-size: 10.5px; }
  }
`;

export class NsPalette extends HTMLElement {
  private shadow: ShadowRoot;
  private unsub?: () => void;
  private root!: HTMLElement;

  constructor() {
    super();
    this.shadow = this.attachShadow({ mode: 'open' });
  }

  connectedCallback(): void {
    this.shadow.appendChild(baseStyle());
    const style = document.createElement('style');
    style.textContent = PALETTE_CSS;
    this.shadow.appendChild(style);

    this.root = document.createElement('div');
    this.root.style.display = 'contents';
    this.shadow.appendChild(this.root);

    this.render();
    this.unsub = ui.subscribe(() => this.render());
  }

  disconnectedCallback(): void {
    this.unsub?.();
  }

  private render(): void {
    const u = ui.get();
    const t = u.tool;

    // Rebuild DOM each render — palette is small and changes infrequently
    this.root.innerHTML = '';

    // Tools group
    const toolGroup = document.createElement('div');
    toolGroup.className = 'group';
    toolGroup.setAttribute('role', 'toolbar');
    toolGroup.setAttribute('aria-label', 'Tools');

    // Select button
    const selectBtn = this.makeToolButton(
      selectGlyph(), 'Select', 'configure',
      t.mode === 'select',
      'Select and configure (Esc)',
      () => setTool({ mode: 'select' }),
    );
    toolGroup.appendChild(selectBtn);

    // Cable button
    const cableBtn = this.makeToolButton(
      cableGlyph(), 'Cable', `$${CABLE_PRICE[u.cableType]}`,
      t.mode === 'cable',
      'Run a cable between two devices',
      () => setTool({ mode: 'cable' }),
    );
    toolGroup.appendChild(cableBtn);

    // Cable type chips (visible when cable tool active)
    if (t.mode === 'cable') {
      const cablesDiv = document.createElement('div');
      cablesDiv.className = 'cables';
      cablesDiv.setAttribute('role', 'radiogroup');
      cablesDiv.setAttribute('aria-label', 'Cable type');
      for (const c of CABLE_TYPES) {
        const chip = document.createElement('button');
        chip.className = 'chip';
        chip.setAttribute('aria-pressed', String(u.cableType === c.type));
        chip.title = `${c.label}, ${CABLE_BANDWIDTH[c.type] / 1000} Gbps`;
        chip.innerHTML = `<span class="swatch" style="background:${c.color}"></span>${c.label}`;
        chip.addEventListener('click', () => {
          ui.update((x) => { x.cableType = c.type; }, 'ui');
        });
        cablesDiv.appendChild(chip);
      }
      toolGroup.appendChild(cablesDiv);
    }

    this.root.appendChild(toolGroup);

    // Separator
    const sep = document.createElement('div');
    sep.className = 'sep';
    this.root.appendChild(sep);

    // Devices group
    const devGroup = document.createElement('div');
    devGroup.className = 'group';
    devGroup.setAttribute('role', 'toolbar');
    devGroup.setAttribute('aria-label', 'Devices');

    for (const k of PLACEABLE_KINDS) {
      const def = DEVICE_DEFS[k];
      const active = t.mode === 'place' && t.kind === k;
      const btn = this.makeToolButton(
        kindGlyph(k), def.label, `$${def.price}`,
        active,
        `${def.label}: ${def.blurb}`,
        () => setTool(active ? { mode: 'select' } : { mode: 'place', kind: k }),
      );
      devGroup.appendChild(btn);
    }

    this.root.appendChild(devGroup);
  }

  private makeToolButton(
    svgHtml: string, name: string, price: string,
    pressed: boolean, title: string, onClick: () => void,
  ): HTMLButtonElement {
    const btn = document.createElement('button');
    btn.className = 'tool';
    btn.setAttribute('aria-pressed', String(pressed));
    btn.title = title;
    btn.innerHTML = `
      <span class="glyph">${svgHtml}</span>
      <span class="name">${name}</span>
      <span class="price">${price}</span>
    `;
    btn.addEventListener('click', onClick);
    return btn;
  }
}
customElements.define('ns-palette', NsPalette);
import { attachInput, fitView, keepSelectionVisible } from './input';
import { Renderer } from './render/renderer';
import { loadAutosave, startAutosave } from './state/persist';
import { sampleWorld } from './state/sample';
import { TICK_MS } from './balance';
import { runtime, toast, ui, world } from './state/world';
import { initSimulation, tick } from './sim/engine';
import './ui/hud';
import './ui/inspector';
import './ui/palette';
import type { NsTopbar } from './ui/hud';

/** True while the user is typing in a panel field, so shortcuts stay out of the way. */
function isUiBusy(): boolean {
  let el: Element | null = document.activeElement;
  while (el?.shadowRoot?.activeElement) el = el.shadowRoot.activeElement;
  return !!el && (el.tagName === 'INPUT' || el.tagName === 'SELECT' || el.tagName === 'TEXTAREA');
}

async function boot(): Promise<void> {
  const stage = document.getElementById('stage')!;
  const renderer = new Renderer();
  await renderer.init(stage);
  document.getElementById('boot')?.remove();

  const saved = await loadAutosave();
  if (saved) {
    world.replace(saved, 'load');
  } else {
    world.replace(sampleWorld(), 'load');
    fitView(renderer);
    toast('Loaded an example network. Press New for an empty layout.');
  }

  attachInput(renderer, isUiBusy);
  keepSelectionVisible(renderer);
  const bar = document.querySelector('ns-topbar') as NsTopbar;
  bar.fit = () => fitView(renderer);
  startAutosave();

  // Phase 2: Start the simulation engine
  world.update((w) => { initSimulation(w); }, 'sim');

  let lastTime = 0;
  let accum = 0;
  const simLoop = (now: number) => {
    if (lastTime > 0) {
      accum += Math.min(now - lastTime, 200); // cap to prevent spiral of death
      while (accum >= TICK_MS) {
        if (world.get().speed > 0) {
          world.update((w) => { tick(w, runtime); }, 'sim');
        }
        accum -= TICK_MS;
      }
    }
    lastTime = now;
    requestAnimationFrame(simLoop);
  };
  requestAnimationFrame(simLoop);

  // expose for debugging in the console
  (window as unknown as { netsim: unknown }).netsim = { world, ui, renderer, runtime };
}

boot().catch((err) => {
  console.error(err);
  const el = document.getElementById('boot');
  if (el) el.textContent = `Could not start the renderer: ${err?.message ?? err}`;
});
